/*
 * Written by scripts/screens.mjs: each Pro screen's file. Only the gated route
 * (src/app/api/screens/[slug]) may import this, so it stays on the server and goes only to Pro
 * accounts. Never import it into a page or a client component. Don't edit by hand.
 */
export const SCREEN_PRO_SOURCES: Record<string, string> = {
  "projects": "\"use client\";\n\nimport { ArchiveIcon, ArrowClockwiseIcon, ArrowUpRightIcon, BookOpenTextIcon, CalendarDotsIcon, ChartLineIcon, ChatCircleIcon, CheckIcon, CoinsIcon, CopyIcon, CreditCardIcon, CubeIcon, DeviceMobileIcon, DotsThreeIcon, EnvelopeSimpleIcon, FolderIcon, FoldersIcon, GearSixIcon, GiftIcon, GitBranchIcon, GlobeHemisphereWestIcon, GlobeSimpleIcon, HouseIcon, LightningIcon, ListIcon, LockKeyIcon, MagnifyingGlassIcon, MegaphoneIcon, NewspaperIcon, PaletteIcon, PlusIcon, PulseIcon, PushPinIcon, RocketLaunchIcon, ShieldCheckIcon, SidebarSimpleIcon, StorefrontIcon, UserPlusIcon, UsersThreeIcon, WarningCircleIcon, XIcon, type Icon } from \"@phosphor-icons/react\";\nimport { AnimatePresence, motion, useReducedMotion } from \"motion/react\";\nimport { useEffect, useRef, useState, type ReactNode } from \"react\";\nimport {\n  AvatarGroup,\n  Breadcrumb,\n  Button,\n  Input,\n  Menu,\n  MenuContent,\n  MenuItem,\n  MenuSeparator,\n  MenuTrigger,\n  Segmented,\n  Sparkline,\n  toast,\n} from \"@basedraft/ui\";\nimport { AccountMenu } from \"@/components/basedraft/account-menu\";\nimport { Allowance } from \"@/components/basedraft/allowance\";\nimport {\n  AppSidebar,\n  type SidebarSection,\n  type SidebarView,\n} from \"@/components/basedraft/app-sidebar\";\nimport { Commit } from \"@/components/basedraft/commit\";\nimport { DataTable, type DataTableColumn } from \"@/components/basedraft/data-table\";\n\n/*\n * A workspace's projects, in an app's frame, as one table: each project's name and address, how it\n * stands (ready, building, failed), its last deployment and the commit in it (or why it needs you),\n * its requests this week, when it last changed, who ships it, and a menu. Every column sorts; pick\n * rows, Shift for a range, and an ink bar offers what can be done to them. What needs you comes\n * first and is named over the table. Filter to the pinned ones or the ones that need you, or\n * search. Click a row and the project's page opens beside the table: what's live, what needs you,\n * its traffic, its last releases and who ships it. It fills the box it's in and scrolls inside, so\n * give that box a height, like h-dvh. The toasts need <Toaster /> once in your root layout.\n */\n\nconst SECTIONS: SidebarSection[] = [\n  {\n    items: [\n      { id: \"overview\", label: \"Overview\", icon: <HouseIcon weight=\"duotone\" />, href: \"/acme\" },\n      { id: \"projects\", label: \"Projects\", icon: <FoldersIcon weight=\"duotone\" />, count: 14, href: \"/acme/projects\" },\n      { id: \"deployments\", label: \"Deployments\", icon: <RocketLaunchIcon weight=\"duotone\" />, busy: true, href: \"/acme/storefront/deployments\" },\n      { id: \"analytics\", label: \"Analytics\", icon: <ChartLineIcon weight=\"duotone\" />, href: \"/acme/storefront/analytics\" },\n      { id: \"roadmap\", label: \"Roadmap\", icon: <CalendarDotsIcon weight=\"duotone\" />, tag: \"New\", href: \"/acme/roadmap\" },\n    ],\n  },\n  {\n    label: \"Pinned\",\n    action: { label: \"Pin a project\", onSelect: () => undefined },\n    items: [\n      { id: \"p-storefront\", label: \"storefront\", icon: <FolderIcon weight=\"duotone\" />, dot: true, href: \"/acme/storefront\" },\n      { id: \"p-docs\", label: \"docs\", icon: <FolderIcon weight=\"duotone\" />, href: \"/acme/docs\" },\n      { id: \"p-api\", label: \"api\", icon: <FolderIcon weight=\"duotone\" />, href: \"/acme/api\" },\n    ],\n  },\n  {\n    label: \"Workspace\",\n    items: [\n      { id: \"members\", label: \"Members\", icon: <UsersThreeIcon weight=\"duotone\" />, href: \"/acme/members\" },\n      { id: \"billing\", label: \"Usage and billing\", icon: <CreditCardIcon weight=\"duotone\" />, href: \"/acme/billing\" },\n      { id: \"settings\", label: \"Settings\", icon: <GearSixIcon weight=\"duotone\" />, href: \"/acme/settings\" },\n    ],\n  },\n];\n\n/* The sidebar's other view: what happened across the workspace, newest first. */\nconst VIEWS: SidebarView[] = [\n  { id: \"home\", label: \"Home\" },\n  {\n    id: \"activity\",\n    label: \"Activity\",\n    sections: [\n      {\n        label: \"Today\",\n        items: [\n          { id: \"a-promote\", label: \"7c2e9a1 is live\", icon: <RocketLaunchIcon weight=\"duotone\" />, count: \"2m\" },\n          { id: \"a-failed\", label: \"gift-cards failed\", icon: <WarningCircleIcon weight=\"duotone\" />, dot: true },\n          { id: \"a-comment\", label: \"Lauren on Checkout\", icon: <ChatCircleIcon weight=\"duotone\" />, count: \"1h\" },\n        ],\n      },\n      {\n        label: \"Yesterday\",\n        items: [\n          { id: \"a-credits\", label: \"$100 of credits\", icon: <CoinsIcon weight=\"duotone\" />, count: \"5pm\" },\n          { id: \"a-invite\", label: \"Tyler Hayes joined\", icon: <UserPlusIcon weight=\"duotone\" />, count: \"3pm\" },\n        ],\n      },\n    ],\n  },\n];\n\n/** The workspace's logo: basedraft's mark on an ink tile, standing in for yours. */\nfunction Mark() {\n  return (\n    <span className=\"grid size-6 shrink-0 place-items-center rounded-[7px] text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.14)]\">\n      <svg width={16} height={16} viewBox=\"0 0 40 40\" aria-hidden>\n        <path d=\"M6.85547 27.2182V12.6708C6.85547 11.2225 7.81635 9.95166 9.20555 9.56255L22.5167 5.83433C24.5479 5.26541 26.565 6.78215 26.5931 8.89956L26.7742 22.5376C26.7927 23.9328 25.9163 25.1818 24.6017 25.6336L11.1095 30.2712C9.02405 30.9879 6.85547 29.4317 6.85547 27.2182Z\" fill=\"currentColor\" />\n        <path d=\"M28.6015 10.8973L16.0958 17.0783L16.0698 17.0949C15.1656 17.6727 14.6078 18.6652 14.5825 19.7411L14.3291 30.5163C14.2766 32.7474 16.4414 34.3571 18.5513 33.6561L31.0303 29.5082C32.3457 29.0709 33.2339 27.8362 33.2339 26.4448V13.7925C33.2339 11.4025 30.7368 9.84189 28.6015 10.8973Z\" fill=\"currentColor\" fillOpacity={0.7} />\n      </svg>\n    </span>\n  );\n}\n\n/** The app around the page: the sidebar (a drawer where it doesn't fit), and the page on a panel under its header, with room on the panel for an inspector. */\nfunction AppFrame({ page, crumbs, actions, panel, children }: { page: string; crumbs: string[]; actions?: ReactNode; panel?: ReactNode; children: ReactNode }) {\n  const [mode, setMode] = useState<\"side\" | \"drawer\">(\"side\");\n  const [open, setOpen] = useState(false);\n  return (\n    <div className=\"@container relative flex h-full min-h-0 bg-[var(--bd-well)] text-[var(--bd-fg)]\">\n      <AppSidebar\n        plain\n        contained\n        breakpoint={900}\n        sections={SECTIONS}\n        views={VIEWS}\n        active={page}\n        workspaces={[\n          { id: \"acme\", name: \"Acme\", plan: \"Team\", logo: <Mark /> },\n          { id: \"personal\", name: \"Personal\", plan: \"Hobby\" },\n        ]}\n        defaultWorkspace=\"acme\"\n        footer={(rail) => <Allowance label=\"Build minutes\" used={5046} limit={6000} projected={6210} note=\"Renews Nov 30\" compact={rail} className={rail ? \"mx-auto\" : undefined} />}\n        account={(rail) => (\n          <AccountMenu\n            user={{ name: \"Emily Carter\", email: \"emily@acme.com\" }}\n            trigger={rail ? \"face\" : \"row\"}\n            defaultNote=\"Planning the fourth quarter\"\n            workspaces={[\n              { id: \"acme\", name: \"Acme\", role: \"Owner\", logo: <Mark /> },\n              { id: \"personal\", name: \"Personal\", role: \"Hobby\" },\n            ]}\n            workspace=\"acme\"\n            onPreferences={() => undefined}\n            onSignOut={() => undefined}\n          />\n        )}\n        onSearch={() => undefined}\n        open={open}\n        onOpenChange={setOpen}\n        onModeChange={setMode}\n      />\n      <div className=\"flex min-w-0 flex-1 flex-col @3xl:py-2 @3xl:pr-2\">\n        <main className=\"@container/main relative flex min-h-0 flex-1 flex-col overflow-hidden bg-[var(--bd-surface)] @3xl:rounded-[14px] @3xl:shadow-[0_0_0_1px_var(--bd-line-subtle),0_1px_3px_rgb(var(--bd-shade)/0.06)]\">\n          <header className=\"flex h-12 shrink-0 items-center gap-2 border-b border-[var(--bd-line-subtle)] px-3 @3xl:px-5\">\n            {mode === \"drawer\" && (\n              <button type=\"button\" onClick={() => setOpen(true)} aria-label=\"Open the menu\" className=\"grid size-8 place-items-center rounded-full text-[var(--bd-muted)] hover:bg-[rgb(var(--bd-ink)/0.06)]\">\n                <ListIcon weight=\"regular\" size={17} />\n              </button>\n            )}\n            <span className=\"min-w-0 @max-xl:hidden\">\n              <Breadcrumb items={crumbs.map((label, i) => (i < crumbs.length - 1 ? { label, href: `/${crumbs.slice(0, i + 1).join(\"/\").toLowerCase()}` } : { label }))} />\n            </span>\n            {/* Where there's no room for the trail, the page's name alone. */}\n            <span className=\"truncate text-[13.5px] font-medium @xl:hidden\">{crumbs.at(-1)}</span>\n            <div className=\"ml-auto flex items-center gap-2\">{actions}</div>\n          </header>\n          {/* The page, and beside it what's opened from it, which pushes the page left as it opens. */}\n          <div className=\"relative flex min-h-0 flex-1\">\n            {/* It scrolls without a bar, the way an app's page does. */}\n            <div className=\"relative min-h-0 min-w-0 flex-1 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden\">{children}</div>\n            {panel}\n          </div>\n        </main>\n      </div>\n    </div>\n  );\n}\n\nconst DAY = 86_400_000;\nconst HOUR = 3_600_000;\n/* Now is Thursday, Nov 12, at 3pm; the history is the two weeks before it. */\nconst NOW = Date.UTC(2026, 10, 12, 15, 0);\nconst FROM = Date.UTC(2026, 9, 30);\n\n/** A small seeded random, so the made-up history is the same on the server and in the browser. */\nfunction seeded(seed: number) {\n  let s = seed;\n  return () => {\n    s = (s + 0x6d2b79f5) | 0;\n    let t = Math.imul(s ^ (s >>> 15), 1 | s);\n    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\n\n/** Times across the two weeks, mostly on weekdays and in working hours, as people ship. */\nfunction times(seed: number, n: number) {\n  const r = seeded(seed);\n  const out: number[] = [];\n  for (let tries = 0; out.length < n && tries < 400; tries++) {\n    const day = FROM + Math.floor(r() * 14) * DAY;\n    const weekend = [0, 6].includes(new Date(day).getUTCDay());\n    if (weekend && r() < 0.85) continue;\n    const at = day + (9 + r() * 10) * HOUR;\n    if (at < NOW - HOUR) out.push(at);\n  }\n  return out.sort((a, b) => a - b);\n}\nconst sha = (seed: number) => Math.floor(seeded(seed)() * 0xfffffff).toString(16).padStart(7, \"0\");\n\n/** What needs you: how the lead says it after the name, the row's short note, the page's full account, and what to do. */\ntype Need = { tone: \"stop\" | \"wait\"; lead: string; note: string; long: string; action: string };\ntype Event = { id: string; at: number; kind: \"ship\" | \"try\" | \"fail\" | \"run\"; label: string };\ntype Project = {\n  id: string;\n  url: string | null;\n  framework: string;\n  icon: Icon;\n  people: string[];\n  /** Requests in the last seven days, and the change on the seven before. */\n  requests: number | null;\n  change?: number;\n  ships: number;\n  tries: number;\n  seed: number;\n  fails?: number[];\n  running?: boolean;\n  pinned?: boolean;\n  needs?: Need;\n  live?: { message: string; branch: string };\n  region: string;\n  created: string;\n};\n\nconst PROJECTS: Project[] = [\n  { id: \"storefront\", url: \"acme.com\", framework: \"Next.js 16\", icon: StorefrontIcon, people: [\"Jake Morrison\", \"Sarah Mitchell\", \"Megan Turner\", \"Emily Carter\"], requests: 1_820_000, change: 12, ships: 9, tries: 16, seed: 11, running: true, pinned: true, live: { message: \"Gift card balance on checkout\", branch: \"main\" }, region: \"iad1, fra1\", created: \"Mar 4, 2025\" },\n  { id: \"api\", url: \"api.acme.com\", framework: \"Node 22\", icon: LightningIcon, people: [\"Ryan Brooks\", \"Tyler Hayes\"], requests: 3_140_000, change: 4, ships: 5, tries: 7, seed: 23, fails: [Date.UTC(2026, 10, 10, 16, 20)], pinned: true, needs: { tone: \"wait\", lead: \"'s errors are up 3× since Tuesday\", note: \"Errors are up 3×\", long: \"Errors are three times higher since Tuesday's release, mostly timeouts on /v2/orders.\", action: \"Open logs\" }, live: { message: \"Paginate orders by cursor\", branch: \"main\" }, region: \"iad1\", created: \"Jan 18, 2025\" },\n  { id: \"gift-cards\", url: null, framework: \"Next.js 16\", icon: GiftIcon, people: [\"Megan Turner\", \"Jake Morrison\"], requests: null, ships: 0, tries: 9, seed: 37, fails: [Date.UTC(2026, 10, 12, 13, 5)], needs: { tone: \"stop\", lead: \" failed to build 2h ago\", note: \"Failed to build 2h ago\", long: \"The last build failed with 2 type errors in checkout/gift-card.tsx, so its preview is behind main.\", action: \"See the log\" }, region: \"iad1\", created: \"Oct 27, 2026\" },\n  { id: \"docs\", url: \"docs.acme.com\", framework: \"Astro 5\", icon: BookOpenTextIcon, people: [\"Sarah Mitchell\", \"Lauren Price\"], requests: 412_000, change: -3, ships: 4, tries: 6, seed: 41, pinned: true, live: { message: \"Webhooks guide for gift cards\", branch: \"main\" }, region: \"iad1\", created: \"Feb 2, 2025\" },\n  { id: \"search\", url: \"search.acme.com\", framework: \"Node 22\", icon: MagnifyingGlassIcon, people: [\"Megan Turner\"], requests: 640_000, change: 21, ships: 3, tries: 5, seed: 53, live: { message: \"Forgive one typo per word\", branch: \"main\" }, region: \"iad1, fra1\", created: \"Jun 9, 2025\" },\n  { id: \"marketing-site\", url: \"launch.acme.com\", framework: \"Astro 5\", icon: MegaphoneIcon, people: [\"Emily Carter\", \"Lauren Price\"], requests: 96_000, change: 38, ships: 3, tries: 4, seed: 67, live: { message: \"Holiday campaign page\", branch: \"main\" }, region: \"iad1\", created: \"Apr 21, 2025\" },\n  { id: \"mobile-web\", url: \"m.acme.com\", framework: \"Next.js 16\", icon: DeviceMobileIcon, people: [\"Jake Morrison\"], requests: 210_000, change: 2, ships: 2, tries: 3, seed: 79, live: { message: \"Faster product images on 4G\", branch: \"main\" }, region: \"iad1\", created: \"Aug 14, 2025\" },\n  { id: \"admin\", url: \"admin.acme.com\", framework: \"Next.js 16\", icon: ShieldCheckIcon, people: [\"Tyler Hayes\", \"Ryan Brooks\"], requests: 18_400, change: 0, ships: 2, tries: 2, seed: 83, live: { message: \"Refunds in two clicks\", branch: \"main\" }, region: \"iad1\", created: \"Mar 30, 2025\" },\n  { id: \"design-system\", url: \"ui.acme.com\", framework: \"Storybook 9\", icon: PaletteIcon, people: [\"Lauren Price\", \"Sarah Mitchell\"], requests: 6_100, change: 9, ships: 4, tries: 3, seed: 97, live: { message: \"Hold button for refunds\", branch: \"main\" }, region: \"iad1\", created: \"May 5, 2025\" },\n  { id: \"blog\", url: \"blog.acme.com\", framework: \"Astro 5\", icon: NewspaperIcon, people: [\"Emily Carter\"], requests: 74_000, change: -8, ships: 2, tries: 1, seed: 101, live: { message: \"Why we moved to fra1\", branch: \"main\" }, region: \"iad1\", created: \"Feb 11, 2025\" },\n  { id: \"auth\", url: \"auth.acme.com\", framework: \"Node 22\", icon: LockKeyIcon, people: [\"Ryan Brooks\"], requests: 880_000, change: 1, ships: 1, tries: 2, seed: 113, live: { message: \"Passkeys on by default\", branch: \"main\" }, region: \"iad1, fra1\", created: \"Jan 18, 2025\" },\n  { id: \"emails\", url: null, framework: \"React Email\", icon: EnvelopeSimpleIcon, people: [\"Lauren Price\"], requests: null, ships: 0, tries: 4, seed: 127, region: \"iad1\", created: \"Sep 22, 2025\" },\n  { id: \"cdn-edge\", url: \"cdn.acme.com\", framework: \"Worker\", icon: GlobeSimpleIcon, people: [\"Tyler Hayes\"], requests: 9_400_000, change: 6, ships: 1, tries: 0, seed: 131, live: { message: \"Cache product images a day\", branch: \"main\" }, region: \"Global\", created: \"Jan 18, 2025\" },\n  { id: \"status-page\", url: \"status.acme.com\", framework: \"Astro 5\", icon: PulseIcon, people: [\"Ryan Brooks\"], requests: 41_000, change: -12, ships: 1, tries: 0, seed: 149, live: { message: \"Show fra1 on the map\", branch: \"main\" }, region: \"iad1\", created: \"Jul 1, 2025\" },\n];\n\n/** A project's two weeks: what shipped, what was tried, what failed, and what's building now. */\nfunction eventsOf(p: Project): Event[] {\n  return [\n    ...times(p.seed, p.ships).map((at, i) => ({ id: `${p.id}-s${i}`, at, kind: \"ship\" as const, label: `Released ${sha(p.seed * 31 + i)}` })),\n    ...times(p.seed * 7 + 3, p.tries).map((at, i) => ({ id: `${p.id}-t${i}`, at, kind: \"try\" as const, label: `Preview ${sha(p.seed * 17 + i)}` })),\n    ...(p.fails ?? []).map((at, i) => ({ id: `${p.id}-f${i}`, at, kind: \"fail\" as const, label: \"Build failed\" })),\n    ...(p.running ? [{ id: `${p.id}-run`, at: NOW, kind: \"run\" as const, label: \"Building now\" }] : []),\n  ].sort((a, b) => a.at - b.at);\n}\nconst EVENTS = Object.fromEntries(PROJECTS.map((p) => [p.id, eventsOf(p)]));\nconst lastOf = (p: Project) => EVENTS[p.id].reduce((m, e) => Math.max(m, e.at), 0);\nconst lastShipOf = (p: Project) => EVENTS[p.id].reduce((m, e) => (e.kind === \"ship\" ? Math.max(m, e.at) : m), lastOf(p) - 30 * DAY);\n/** What needs you first, then the pinned, then the rest by their latest release. */\nconst ORDER = [...PROJECTS].sort((a, b) => Number(!!b.needs) - Number(!!a.needs) || Number(!!b.pinned) - Number(!!a.pinned) || lastShipOf(b) - lastShipOf(a));\n\n/** Fourteen days of a project's requests: weekdays busier than weekends, its own wobble. */\nfunction trafficOf(p: Project) {\n  if (!p.requests) return [];\n  const r = seeded(p.seed * 3);\n  return Array.from({ length: 14 }, (_, i) => {\n    const weekend = [0, 6].includes(new Date(FROM + i * DAY).getUTCDay());\n    const base = (p.requests! / 7) * (weekend ? 0.72 : 1.1);\n    return Math.round(base * (0.86 + r() * 0.28) * (1 + ((p.change ?? 0) / 100) * (i / 13)));\n  });\n}\n\nconst compact = (n: number) => new Intl.NumberFormat(\"en-US\", { notation: \"compact\", maximumFractionDigits: 1 }).format(n);\nconst ago = (t: number) => {\n  const h = (NOW - t) / HOUR;\n  if (h < 1) return \"Just now\";\n  if (h < 24) return `${Math.round(h)}h ago`;\n  if (h < 48) return \"Yesterday\";\n  return new Date(t).toLocaleDateString(\"en-US\", { month: \"short\", day: \"numeric\", timeZone: \"UTC\" });\n};\n\nconst TONE = { stop: \"bg-[var(--bd-ui-stop)]\", wait: \"bg-[var(--bd-ui-wait)]\" } as const;\n\n/** A project's mark: its icon on a quiet tile, with a dot at the corner when it needs you. */\nfunction Tile({ p, size = \"md\" }: { p: Project; size?: \"md\" | \"lg\" }) {\n  return (\n    <span className={`relative grid shrink-0 place-items-center bg-[var(--bd-raised)] text-[var(--bd-fg)] shadow-[0_0_0_1px_rgb(var(--bd-ink)/0.08),0_1px_2px_rgb(var(--bd-shade)/0.06)] ${size === \"lg\" ? \"size-11 rounded-[12px] [&_svg]:size-[22px]\" : \"size-8 rounded-[9px] [&_svg]:size-[17px]\"}`}>\n      <p.icon weight=\"duotone\" aria-hidden />\n      {p.needs && <span aria-hidden className={`absolute -right-0.5 -top-0.5 size-2.5 rounded-full shadow-[0_0_0_2px_var(--bd-surface)] ${TONE[p.needs.tone]}`} />}\n    </span>\n  );\n}\n\n/** A name in the lead's sentence that opens its project. */\nfunction Named({ p, onOpen }: { p: Project; onOpen: (id: string) => void }) {\n  return (\n    <button type=\"button\" onClick={() => onOpen(p.id)} className=\"font-medium text-[var(--bd-fg)] underline decoration-[rgb(var(--bd-ink)/0.2)] underline-offset-[5px] transition-colors hover:decoration-[var(--bd-fg)]\">\n      {p.id}\n    </button>\n  );\n}\n\n/** A quiet button that copies an address, with a check for a moment once it has. */\nfunction CopyAddress({ url }: { url: string }) {\n  const [done, setDone] = useState(false);\n  useEffect(() => {\n    if (!done) return;\n    const t = window.setTimeout(() => setDone(false), 1400);\n    return () => window.clearTimeout(t);\n  }, [done]);\n  return (\n    <button type=\"button\" onClick={() => void navigator.clipboard?.writeText(`https://${url}`).then(() => setDone(true))} aria-label={done ? \"Copied\" : `Copy ${url}`} className=\"grid size-7 place-items-center rounded-full text-[var(--bd-subtle)] transition-colors hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\">\n      {done ? <CheckIcon weight=\"bold\" className=\"size-3.5 text-[var(--bd-fg)]\" /> : <CopyIcon weight=\"regular\" className=\"size-3.5\" />}\n    </button>\n  );\n}\n\n/** Under a small title, rows ruled by hairlines. */\nfunction Ruled({ title, end, children }: { title: string; end?: ReactNode; children: ReactNode }) {\n  return (\n    <section aria-label={title} className=\"min-w-0\">\n      <div className=\"flex items-baseline justify-between gap-3 pb-2\">\n        <h3 className=\"text-[12.5px] font-medium text-[var(--bd-muted)]\">{title}</h3>\n        {end}\n      </div>\n      <div className=\"divide-y divide-[var(--bd-line-subtle)] border-y border-[var(--bd-line-subtle)]\">{children}</div>\n    </section>\n  );\n}\n\nconst KIND = {\n  ship: \"h-3.5 w-[3px] rounded-full bg-[var(--bd-fg)]\",\n  try: \"h-2.5 w-[2px] rounded-full bg-[rgb(var(--bd-ink)/0.3)]\",\n  fail: \"size-[7px] rounded-full bg-[var(--bd-ui-stop)]\",\n  run: \"size-[8px] rounded-full border-2 border-[var(--bd-fg)]\",\n} as const;\n\n/**\n * A project's page, beside the list: its name and address, what needs you, what's live, how it's\n * set up, its traffic, its last releases and who ships it, with a way into the project at its foot.\n */\nfunction ProjectPage({ p, onClose }: { p: Project; onClose: () => void }) {\n  const head = useRef<HTMLHeadingElement>(null);\n  useEffect(() => head.current?.focus({ preventScroll: true }), [p.id]);\n  const events = [...EVENTS[p.id]].reverse().slice(0, 5);\n  const traffic = trafficOf(p);\n  const lastShip = [...EVENTS[p.id]].reverse().find((e) => e.kind === \"ship\");\n  const soon = (what: string) => toast(what, { description: `In your app this opens ${p.id}'s own page.` });\n  const specs: Array<[Icon, string, ReactNode]> = [\n    [CubeIcon, \"Framework\", p.framework],\n    [GlobeHemisphereWestIcon, \"Regions\", p.region],\n    [UsersThreeIcon, \"People\", (\n      <span key=\"people\" className=\"flex items-center justify-end gap-2.5\">\n        <AvatarGroup people={p.people.map((name) => ({ name }))} max={3} size=\"sm\" />\n        <span className=\"tabular-nums\">{p.people.length}</span>\n      </span>\n    )],\n    [CalendarDotsIcon, \"Created\", p.created],\n  ];\n  return (\n    <motion.div\n      aria-labelledby=\"project-title\"\n      initial={{ opacity: 0 }}\n      animate={{ opacity: 1 }}\n      transition={{ duration: 0.2 }}\n      onKeyDown={(e) => {\n        if (e.key === \"Escape\" && !e.defaultPrevented) {\n          e.preventDefault();\n          onClose();\n        }\n      }}\n      className=\"flex h-full min-h-0 flex-col\"\n    >\n      <header className=\"flex items-center gap-3 border-b border-[var(--bd-line-subtle)] px-5 py-4\">\n        <Tile p={p} size=\"lg\" />\n        <div className=\"min-w-0 flex-1\">\n          <h2 id=\"project-title\" ref={head} tabIndex={-1} className=\"truncate text-[17px] font-semibold tracking-[-0.012em] outline-none\">\n            {p.id}\n          </h2>\n          <p className=\"flex min-w-0 items-center gap-1 text-[13px] text-[var(--bd-muted)]\">\n            {p.url ? (\n              <>\n                <span className=\"truncate font-mono text-[12.5px]\">{p.url}</span>\n                <CopyAddress url={p.url} />\n              </>\n            ) : (\n              \"Previews only, not in production yet\"\n            )}\n          </p>\n        </div>\n        <button type=\"button\" onClick={onClose} aria-label=\"Close\" className=\"-mr-1.5 grid size-8 shrink-0 place-items-center self-start rounded-full text-[var(--bd-muted)] hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\">\n          <XIcon weight=\"regular\" className=\"size-4\" />\n        </button>\n      </header>\n\n      <div className=\"grid min-h-0 flex-1 content-start gap-7 overflow-y-auto px-5 pb-6 pt-5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden\">\n        {/* What needs you, first, when something does. */}\n        {p.needs && (\n          <div className=\"grid gap-3 rounded-[14px] bg-[rgb(var(--bd-ink)/0.035)] p-4 shadow-[inset_0_0_0_1px_rgb(var(--bd-ink)/0.05)]\">\n            <p className=\"flex items-start gap-2.5 text-[14px] leading-relaxed\">\n              <WarningCircleIcon weight=\"duotone\" aria-hidden className={`mt-[3px] size-[18px] shrink-0 ${p.needs.tone === \"stop\" ? \"text-[var(--bd-ui-stop)]\" : \"text-[var(--bd-ui-wait)]\"}`} />\n              {p.needs.long}\n            </p>\n            <Button variant=\"outline\" size=\"sm\" className=\"justify-self-start\" onClick={() => toast(p.needs!.action, { description: `In your app this opens ${p.id}'s logs.` })}>\n              {p.needs.action}\n            </Button>\n          </div>\n        )}\n\n        {/* What's live. */}\n        {p.live && lastShip ? (\n          <section aria-label=\"Live now\" className=\"grid gap-3\">\n            <h3 className=\"text-[12.5px] font-medium text-[var(--bd-muted)]\">Live now</h3>\n            <Commit layout=\"stack\" message={p.live.message} sha={`${sha(p.seed * 31 + EVENTS[p.id].filter((e) => e.kind === \"ship\").length - 1)}e1c4b29a0f3d`} branch={p.live.branch} author={p.people[0]} time={ago(lastShip.at)} />\n          </section>\n        ) : (\n          <p className=\"text-[14px] leading-relaxed text-[var(--bd-muted)]\">Nothing is live yet. Its previews build on every push; promote one when it&apos;s ready.</p>\n        )}\n\n        {/* Traffic, when it has any. */}\n        {traffic.length > 0 && (\n          <section aria-label=\"Traffic\" className=\"grid gap-3\">\n            <div className=\"flex items-baseline justify-between gap-3\">\n              <h3 className=\"text-[12.5px] font-medium text-[var(--bd-muted)]\">Requests, 7 days</h3>\n              <span className=\"text-[12.5px] tabular-nums text-[var(--bd-muted)]\">{p.change ? `${p.change > 0 ? \"Up\" : \"Down\"} ${Math.abs(p.change)}% on the week before` : \"Level with the week before\"}</span>\n            </div>\n            <p className=\"text-[28px] font-semibold leading-none tracking-[-0.025em] tabular-nums\">{compact(p.requests!)}</p>\n            <Sparkline data={traffic} height={56} color=\"var(--bd-fg)\" label={`${p.id} requests, last 14 days`} />\n          </section>\n        )}\n\n        <Ruled title=\"Project\">\n          {specs.map(([I, k, v]) => (\n            <div key={k} className=\"flex min-h-11 items-center justify-between gap-4 py-2\">\n              <span className=\"flex items-center gap-3 text-[13px] text-[var(--bd-muted)]\">\n                <I weight=\"duotone\" aria-hidden className=\"size-4 shrink-0 text-[var(--bd-subtle)]\" />\n                {k}\n              </span>\n              <span className=\"min-w-0 truncate text-right text-[13.5px]\">{v}</span>\n            </div>\n          ))}\n        </Ruled>\n\n        <Ruled title=\"Lately\" end={<span className=\"text-[12px] text-[var(--bd-subtle)]\">Two weeks</span>}>\n          {events.length ? (\n            events.map((e) => (\n              <div key={e.id} className=\"flex min-h-11 items-center gap-3 py-2 text-[13.5px]\">\n                <span className=\"grid size-4 shrink-0 place-items-center\" aria-hidden>\n                  <span className={KIND[e.kind]} />\n                </span>\n                <span className={`min-w-0 flex-1 truncate ${e.kind === \"fail\" ? \"text-[var(--bd-ui-stop)]\" : \"\"}`}>{e.label}</span>\n                <span className=\"shrink-0 text-[12.5px] tabular-nums text-[var(--bd-subtle)]\">{e.kind === \"run\" ? \"Now\" : ago(e.at)}</span>\n              </div>\n            ))\n          ) : (\n            <p className=\"py-3 text-[13.5px] text-[var(--bd-muted)]\">Nothing in two weeks.</p>\n          )}\n        </Ruled>\n      </div>\n\n      <footer className=\"flex items-center justify-end gap-2 border-t border-[var(--bd-line-subtle)] px-5 py-3\">\n        {p.url && (\n          <Button variant=\"ghost\" size=\"sm\" onClick={() => toast(`Opening ${p.url}`, { description: \"In your app this opens in a new tab.\" })}>\n            Visit <ArrowUpRightIcon weight=\"regular\" />\n          </Button>\n        )}\n        <Button variant=\"outline\" size=\"sm\" onClick={() => soon(\"Settings\")}>\n          Settings\n        </Button>\n        <Button size=\"sm\" onClick={() => soon(\"Open project\")}>\n          Open project\n        </Button>\n      </footer>\n    </motion.div>\n  );\n}\n\n/* The side panel's width, open. */\nconst SIDE = 440;\n\n/**\n * Where an opened deployment shows, at the page's right. It opens by widening from nothing, so on a\n * wide screen the page eases left to make room, and on a narrow one, with no room to share, it lies\n * over the page instead. What's in it keeps its full width throughout, held to the right, so it\n * slides in rather than squeezes.\n */\nfunction Side({ label, children }: { label: string; children: ReactNode }) {\n  const still = useReducedMotion();\n  return (\n    <motion.aside\n      aria-label={label}\n      initial={{ width: 0 }}\n      animate={{ width: SIDE }}\n      exit={{ width: 0 }}\n      transition={still ? { duration: 0 } : { type: \"spring\", stiffness: 340, damping: 40, mass: 0.9 }}\n      className=\"relative h-full max-w-full shrink-0 overflow-hidden border-l border-[var(--bd-line-subtle)] bg-[var(--bd-surface)] @max-4xl/main:absolute @max-4xl/main:inset-y-0 @max-4xl/main:right-0 @max-4xl/main:z-20 @max-4xl/main:border-l-0 @max-4xl/main:shadow-[0_0_0_1px_rgb(var(--bd-ink)/0.08),-24px_0_48px_-24px_rgb(var(--bd-shade)/0.4)]\"\n    >\n      <div className=\"absolute inset-y-0 right-0 w-[min(440px,100cqw)]\">{children}</div>\n    </motion.aside>\n  );\n}\n\n/** How a project stands now: a dot and a word, and its place when sorting by it, worst first. */\nfunction lookOf(p: Project) {\n  if (p.needs?.tone === \"stop\") return { dot: \"bg-[var(--bd-ui-stop)]\", word: \"Failed\", live: false, rank: 0 };\n  if (p.needs) return { dot: \"bg-[var(--bd-ui-wait)]\", word: \"Errors\", live: false, rank: 1 };\n  if (p.running) return { dot: \"bg-[var(--bd-ui-wait)]\", word: \"Building\", live: true, rank: 2 };\n  if (p.url) return { dot: \"bg-[var(--bd-ui-ok)]\", word: \"Ready\", live: false, rank: 3 };\n  return { dot: \"bg-[var(--bd-subtle)]\", word: \"Previews\", live: false, rank: 4 };\n}\n\n/** A project's state: a dot and its word. The dot breathes while it builds. */\nfunction Status({ p }: { p: Project }) {\n  const still = useReducedMotion();\n  const look = lookOf(p);\n  return (\n    <span className=\"inline-flex items-center gap-2 whitespace-nowrap text-[13.5px]\">\n      <span className=\"relative grid size-2 shrink-0 place-items-center\">\n        {look.live && !still && <motion.span className={`absolute inset-0 rounded-full ${look.dot}`} animate={{ scale: [1, 2.4], opacity: [0.5, 0] }} transition={{ duration: 1.4, repeat: Infinity, ease: \"easeOut\" }} />}\n        <span className={`relative size-2 rounded-full ${look.dot}`} />\n      </span>\n      {look.word}\n    </span>\n  );\n}\n\nconst lastShipEvent = (p: Project) => [...EVENTS[p.id]].reverse().find((e) => e.kind === \"ship\");\nconst shaOf = (p: Project) => sha(p.seed * 31 + EVENTS[p.id].filter((e) => e.kind === \"ship\").length - 1);\n\n/** What a project can do, in its row's menu. */\nfunction RowMenu({ p, onOpen }: { p: Project; onOpen: (id: string) => void }) {\n  const say = (what: string, description: string) => () => toast(what, { description });\n  return (\n    <Menu>\n      <MenuTrigger aria-label={`More for ${p.id}`} className=\"grid size-8 place-items-center rounded-full text-[var(--bd-muted)] transition-colors hover:bg-[rgb(var(--bd-ink)/0.07)] hover:text-[var(--bd-fg)] aria-expanded:bg-[rgb(var(--bd-ink)/0.07)]\">\n        <DotsThreeIcon weight=\"bold\" className=\"size-4\" />\n      </MenuTrigger>\n      <MenuContent align=\"end\">\n        <MenuItem icon={<SidebarSimpleIcon weight=\"duotone\" />} onSelect={() => onOpen(p.id)}>\n          Open beside the list\n        </MenuItem>\n        {p.url && (\n          <MenuItem icon={<ArrowUpRightIcon weight=\"regular\" />} onSelect={say(`Opening ${p.url}`, \"In your app this opens in a new tab.\")}>\n            Visit {p.url}\n          </MenuItem>\n        )}\n        <MenuItem icon={<ArrowClockwiseIcon weight=\"regular\" />} onSelect={say(`Redeploying ${p.id}`, \"Production builds again from main.\")}>\n          Redeploy\n        </MenuItem>\n        <MenuItem icon={<PushPinIcon weight=\"duotone\" />} onSelect={say(p.pinned ? `Unpinned ${p.id}` : `Pinned ${p.id}`, \"The sidebar shows your pinned projects.\")}>\n          {p.pinned ? \"Unpin\" : \"Pin to the sidebar\"}\n        </MenuItem>\n        <MenuSeparator />\n        <MenuItem icon={<GearSixIcon weight=\"duotone\" />} onSelect={say(\"Settings\", `In your app this opens ${p.id}'s settings.`)}>\n          Settings\n        </MenuItem>\n      </MenuContent>\n    </Menu>\n  );\n}\n\n/* The columns that step out first when there's no room for them, in order. */\nconst OUT = [\"people\", \"updated\", \"requests\", \"last\", \"status\"];\n\n/** The table's columns: what each shows, and how it sorts. */\nconst columnsFor = (onOpen: (id: string) => void): DataTableColumn<Project>[] => [\n  {\n    key: \"project\",\n    header: \"Project\",\n    width: \"220px\",\n    sortBy: (p) => p.id,\n    cell: (p) => (\n      <span className=\"flex w-[188px] min-w-0 items-center gap-3 normal-nums\">\n        <Tile p={p} />\n        <span className=\"min-w-0\">\n          <span className=\"block truncate text-[14px] font-medium\">{p.id}</span>\n          <span className=\"block truncate text-[12.5px] font-normal text-[var(--bd-muted)]\">{p.url ?? \"Previews only\"}</span>\n        </span>\n      </span>\n    ),\n  },\n  { key: \"status\", header: \"Status\", width: \"120px\", sortBy: (p) => lookOf(p).rank, cell: (p) => <Status p={p} /> },\n  {\n    key: \"last\",\n    header: \"Last deployment\",\n    cell: (p) => {\n      const last = lastShipEvent(p);\n      return (\n        // No width of its own (w-0), then all the room the other columns leave (min-w-full): this\n        // column gives way first, truncating, so the table never has to be wider than its box.\n        <span className=\"block w-0 min-w-full normal-nums\">\n          {p.needs ? (\n            <>\n              <span className={`block truncate text-[13.5px] ${p.needs.tone === \"stop\" ? \"text-[var(--bd-ui-stop)]\" : \"text-[var(--bd-ui-wait)]\"}`}>{p.needs.tone === \"stop\" ? \"Build failed with 2 type errors\" : \"Errors up 3× since Tuesday\"}</span>\n              <span className=\"block truncate font-mono text-[12px] text-[var(--bd-subtle)]\">{p.needs.tone === \"stop\" ? \"main · checkout/gift-card.tsx\" : `main · ${shaOf(p)}`}</span>\n            </>\n          ) : p.live && last ? (\n            <>\n              <span className=\"block truncate text-[13.5px]\">{p.live.message}</span>\n              <span className=\"flex items-center gap-1.5 truncate font-mono text-[12px] text-[var(--bd-subtle)]\">\n                <GitBranchIcon weight=\"regular\" aria-hidden className=\"size-3 shrink-0\" />\n                {p.live.branch} · {shaOf(p)}\n              </span>\n            </>\n          ) : (\n            <>\n              <span className=\"block truncate text-[13.5px] text-[var(--bd-muted)]\">No release yet</span>\n              <span className=\"block truncate text-[12px] text-[var(--bd-subtle)]\">{EVENTS[p.id].filter((e) => e.kind === \"try\").length} previews built</span>\n            </>\n          )}\n        </span>\n      );\n    },\n  },\n  {\n    key: \"requests\",\n    header: \"Requests, 7d\",\n    align: \"end\",\n    width: \"136px\",\n    sortBy: (p) => p.requests ?? -1,\n    cell: (p) =>\n      p.requests ? (\n        <span className=\"inline-flex items-baseline justify-end gap-2 whitespace-nowrap\">\n          <span className=\"text-[13.5px]\">{compact(p.requests)}</span>\n          <span className={`w-11 text-right text-[12px] ${p.change && p.change < -5 ? \"text-[var(--bd-ui-wait)]\" : \"text-[var(--bd-subtle)]\"}`}>{p.change ? `${p.change > 0 ? \"+\" : \"−\"}${Math.abs(p.change)}%` : \"0%\"}</span>\n        </span>\n      ) : (\n        <span className=\"text-[13.5px] text-[var(--bd-subtle)]\">None</span>\n      ),\n  },\n  { key: \"updated\", header: \"Updated\", align: \"end\", width: \"112px\", sortBy: (p) => lastOf(p), cell: (p) => <span className=\"whitespace-nowrap text-[13.5px] text-[var(--bd-muted)]\">{p.running ? \"Building\" : ago(lastOf(p))}</span> },\n  {\n    key: \"people\",\n    header: \"People\",\n    width: \"120px\",\n    sortBy: (p) => p.people.length,\n    cell: (p) => <AvatarGroup people={p.people.map((name) => ({ name }))} max={3} size=\"sm\" />,\n  },\n  { key: \"menu\", header: <span className=\"sr-only\">Actions</span>, width: \"56px\", cell: (p) => <RowMenu p={p} onOpen={onOpen} /> },\n];\n\nexport default function ProjectsScreen() {\n  const [show, setShow] = useState(\"all\");\n  const [query, setQuery] = useState(\"\");\n  const [open, setOpen] = useState<string | null>(null);\n  const needing = PROJECTS.filter((p) => p.needs);\n  const weekShips = Object.values(EVENTS)\n    .flat()\n    .filter((e) => e.kind === \"ship\" && e.at > NOW - 7 * DAY).length;\n  const q = query.trim().toLowerCase();\n  const shown = ORDER.filter((p) => (show === \"pinned\" ? p.pinned : show === \"needs\" ? p.needs : true)).filter((p) => !q || p.id.includes(q) || (p.url ?? \"\").includes(q));\n  const project = PROJECTS.find((p) => p.id === open);\n  const toggle = (id: string) => setOpen((o) => (o === id ? null : id));\n  // The table always fits the space it has, never scrolling sideways: the last deployment takes\n  // what's left and truncates, and as the space narrows the columns that matter least step out,\n  // people first, then the figures, then the last deployment itself.\n  const box = useRef<HTMLDivElement>(null);\n  const [room, setRoom] = useState(1176);\n  useEffect(() => {\n    const el = box.current;\n    if (!el) return;\n    const ro = new ResizeObserver(([e]) => setRoom(e.contentRect.width));\n    ro.observe(el);\n    return () => ro.disconnect();\n  }, []);\n  // The fixed columns with 220 for the last deployment need 1,028 with everyone, 908 without\n  // people, 660 without the figures and 440 without the last deployment; each step keeps 30 spare.\n  const stepped = room < 540 ? 5 : room < 690 ? 4 : room < 940 ? 3 : room < 1060 ? 1 : 0;\n  const hidden = new Set(OUT.slice(0, stepped));\n  const columns = columnsFor(toggle).filter((c) => !hidden.has(c.key));\n  const many = (ids: string[]) => (ids.length === 1 ? ids[0] : `${ids.length} projects`);\n\n  return (\n    <AppFrame\n      page=\"projects\"\n      crumbs={[\"Acme\", \"Projects\"]}\n      actions={\n        <Button size=\"sm\" onClick={() => toast(\"New project\", { description: \"In your app this imports a repository.\" })}>\n          <PlusIcon weight=\"regular\" /> New project\n        </Button>\n      }\n      panel={\n        <AnimatePresence initial={false}>\n          {project && (\n            <Side key=\"side\" label={`${project.id}`}>\n              <ProjectPage key={project.id} p={project} onClose={() => setOpen(null)} />\n            </Side>\n          )}\n        </AnimatePresence>\n      }\n    >\n      <div className=\"@container/page mx-auto grid w-full max-w-[1240px] grid-cols-[minmax(0,1fr)] gap-6 px-4 pb-16 pt-8 @2xl:px-8 @2xl:pt-10\">\n        <div className=\"flex flex-wrap items-end justify-between gap-x-6 gap-y-4\">\n          <div className=\"grid gap-1.5\">\n            <h1 className=\"flex items-baseline gap-2.5 text-[26px] font-semibold leading-tight tracking-[-0.025em]\">\n              Projects <span className=\"text-[17px] font-medium tabular-nums text-[var(--bd-subtle)]\">{PROJECTS.length}</span>\n            </h1>\n            <p className=\"text-[14.5px] text-[var(--bd-muted)]\">\n              <span className=\"tabular-nums text-[var(--bd-fg)]\">{weekShips}</span> releases this week.{\" \"}\n              {needing.length > 0 && (\n                <>\n                  {needing.map((p, i) => (\n                    <span key={p.id}>\n                      {i > 0 && (i === needing.length - 1 ? \" and \" : \", \")}\n                      <Named p={p} onOpen={toggle} />\n                    </span>\n                  ))}{\" \"}\n                  need you.\n                </>\n              )}\n            </p>\n          </div>\n          <div className=\"flex w-full flex-wrap items-center gap-3 @2xl/page:w-auto\">\n            <Segmented\n              size=\"sm\"\n              label=\"Show\"\n              value={show}\n              onValueChange={setShow}\n              options={[\n                { value: \"all\", label: \"All\" },\n                { value: \"pinned\", label: \"Pinned\" },\n                { value: \"needs\", label: `Needs you ${needing.length}` },\n              ]}\n            />\n            <Input size=\"sm\" placeholder=\"Find a project\" aria-label=\"Find a project\" value={query} onChange={(e) => setQuery(e.target.value)} leading={<MagnifyingGlassIcon weight=\"regular\" />} className=\"min-w-0 flex-1 @2xl/page:w-[220px] @2xl/page:flex-none\" />\n          </div>\n        </div>\n\n        <div ref={box} className=\"min-w-0\">\n        <DataTable\n          label=\"Projects\"\n          rows={shown}\n          columns={columns}\n          rowKey={(p) => p.id}\n          rowLabel={(p) => p.id}\n          selectable={room >= 540}\n          stickyFirstColumn\n          onRowClick={(p) => toggle(p.id)}\n          active={open}\n          empty={<span className=\"text-[14px] text-[var(--bd-muted)]\">No project called &ldquo;{query}&rdquo;.</span>}\n          actions={(picked, clear) => (\n            <>\n              <button type=\"button\" onClick={() => {\n                  toast(`Redeploying ${many(picked)}`, { description: \"Production builds again from main.\" });\n                  clear();\n                }}>\n                <ArrowClockwiseIcon weight=\"regular\" /> Redeploy\n              </button>\n              <button type=\"button\" onClick={() => {\n                  toast(`Pinned ${many(picked)}`, { description: \"The sidebar shows your pinned projects.\" });\n                  clear();\n                }}>\n                <PushPinIcon weight=\"duotone\" /> Pin\n              </button>\n              <button type=\"button\" onClick={() => {\n                  toast(`Archived ${many(picked)}`, { description: \"Archived projects stop building and keep their history.\" });\n                  clear();\n                }}>\n                <ArchiveIcon weight=\"duotone\" /> Archive\n              </button>\n            </>\n          )}\n        />\n        </div>\n      </div>\n    </AppFrame>\n  );\n}\n",
  "deployments": "\"use client\";\n\nimport { ArrowBendDownRightIcon, ArrowClockwiseIcon, ArrowCounterClockwiseIcon, ArrowUpRightIcon, CalendarDotsIcon, ChartLineIcon, ChatCircleIcon, CheckIcon, CircleHalfIcon, CoinsIcon, CopyIcon, CreditCardIcon, DotsThreeIcon, EyeIcon, FolderIcon, FoldersIcon, GearSixIcon, GitBranchIcon, GlobeHemisphereWestIcon, GlobeSimpleIcon, HouseIcon, LinkSimpleIcon, ListIcon, MagnifyingGlassIcon, ProhibitIcon, RocketLaunchIcon, StackIcon, TimerIcon, UserIcon, UserPlusIcon, UsersThreeIcon, WarningCircleIcon, XIcon } from \"@phosphor-icons/react\";\nimport { AnimatePresence, motion, useReducedMotion } from \"motion/react\";\nimport { useEffect, useRef, useState, type ReactNode } from \"react\";\nimport {\n  Breadcrumb,\n  Button,\n  HoldButton,\n  Menu,\n  MenuContent,\n  MenuItem,\n  MenuSeparator,\n  MenuTrigger,\n  SplitButton,\n  toast,\n} from \"@basedraft/ui\";\nimport { AccountMenu } from \"@/components/basedraft/account-menu\";\nimport { Allowance } from \"@/components/basedraft/allowance\";\nimport {\n  AppSidebar,\n  type SidebarSection,\n  type SidebarView,\n} from \"@/components/basedraft/app-sidebar\";\nimport { Commit } from \"@/components/basedraft/commit\";\nimport { FilterBar, type Filter, type FilterField } from \"@/components/basedraft/filter-bar\";\nimport { LogViewer, type LogLine } from \"@/components/basedraft/log-viewer\";\nimport {\n  formatDuration,\n  Pipeline,\n  type PipelineStage,\n  type PipelineStatus,\n} from \"@/components/basedraft/pipeline\";\n\n/*\n * A project's deployments, in an app's frame. What's happening now leads: the push that's\n * building, its stages turning over on a pipeline with the stage's output under it, then, once\n * it's ready, a hold to send it to production. With nothing in flight, the lead is what's live,\n * with a hold to roll back. Under it, every deployment by day, filtered in place; open one for\n * its stages, each stage's log, its domains and what can be done with it. Redeploy builds\n * production again and puts it live when it's ready. It fills the box it's in and scrolls\n * inside, so give that box a height, like h-dvh. The toasts need <Toaster /> once in your root\n * layout.\n */\n\nconst SECTIONS: SidebarSection[] = [\n  {\n    items: [\n      { id: \"overview\", label: \"Overview\", icon: <HouseIcon weight=\"duotone\" />, href: \"/acme\" },\n      { id: \"projects\", label: \"Projects\", icon: <FoldersIcon weight=\"duotone\" />, count: 14, href: \"/acme/projects\" },\n      { id: \"deployments\", label: \"Deployments\", icon: <RocketLaunchIcon weight=\"duotone\" />, href: \"/acme/storefront/deployments\" },\n      { id: \"analytics\", label: \"Analytics\", icon: <ChartLineIcon weight=\"duotone\" />, href: \"/acme/storefront/analytics\" },\n      { id: \"roadmap\", label: \"Roadmap\", icon: <CalendarDotsIcon weight=\"duotone\" />, tag: \"New\", href: \"/acme/roadmap\" },\n    ],\n  },\n  {\n    label: \"Pinned\",\n    action: { label: \"Pin a project\", onSelect: () => undefined },\n    items: [\n      { id: \"p-storefront\", label: \"storefront\", icon: <FolderIcon weight=\"duotone\" />, dot: true, href: \"/acme/storefront\" },\n      { id: \"p-docs\", label: \"docs\", icon: <FolderIcon weight=\"duotone\" />, href: \"/acme/docs\" },\n      { id: \"p-api\", label: \"api\", icon: <FolderIcon weight=\"duotone\" />, href: \"/acme/api\" },\n    ],\n  },\n  {\n    label: \"Workspace\",\n    items: [\n      { id: \"members\", label: \"Members\", icon: <UsersThreeIcon weight=\"duotone\" />, href: \"/acme/members\" },\n      { id: \"billing\", label: \"Usage and billing\", icon: <CreditCardIcon weight=\"duotone\" />, href: \"/acme/billing\" },\n      { id: \"settings\", label: \"Settings\", icon: <GearSixIcon weight=\"duotone\" />, href: \"/acme/settings\" },\n    ],\n  },\n];\n\n/* The sidebar's other view: what happened across the workspace, newest first. */\nconst VIEWS: SidebarView[] = [\n  { id: \"home\", label: \"Home\" },\n  {\n    id: \"activity\",\n    label: \"Activity\",\n    sections: [\n      {\n        label: \"Today\",\n        items: [\n          { id: \"a-promote\", label: \"7c2e9a1 is live\", icon: <RocketLaunchIcon weight=\"duotone\" />, count: \"2m\" },\n          { id: \"a-failed\", label: \"gift-cards failed\", icon: <WarningCircleIcon weight=\"duotone\" />, dot: true },\n          { id: \"a-comment\", label: \"Lauren on Checkout\", icon: <ChatCircleIcon weight=\"duotone\" />, count: \"1h\" },\n        ],\n      },\n      {\n        label: \"Yesterday\",\n        items: [\n          { id: \"a-credits\", label: \"$100 of credits\", icon: <CoinsIcon weight=\"duotone\" />, count: \"5pm\" },\n          { id: \"a-invite\", label: \"Tyler Hayes joined\", icon: <UserPlusIcon weight=\"duotone\" />, count: \"3pm\" },\n        ],\n      },\n    ],\n  },\n];\n\n/** The workspace's logo: basedraft's mark on an ink tile, standing in for yours. */\nfunction Mark() {\n  return (\n    <span className=\"grid size-6 shrink-0 place-items-center rounded-[7px] text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.14)]\">\n      <svg width={16} height={16} viewBox=\"0 0 40 40\" aria-hidden>\n        <path d=\"M6.85547 27.2182V12.6708C6.85547 11.2225 7.81635 9.95166 9.20555 9.56255L22.5167 5.83433C24.5479 5.26541 26.565 6.78215 26.5931 8.89956L26.7742 22.5376C26.7927 23.9328 25.9163 25.1818 24.6017 25.6336L11.1095 30.2712C9.02405 30.9879 6.85547 29.4317 6.85547 27.2182Z\" fill=\"currentColor\" />\n        <path d=\"M28.6015 10.8973L16.0958 17.0783L16.0698 17.0949C15.1656 17.6727 14.6078 18.6652 14.5825 19.7411L14.3291 30.5163C14.2766 32.7474 16.4414 34.3571 18.5513 33.6561L31.0303 29.5082C32.3457 29.0709 33.2339 27.8362 33.2339 26.4448V13.7925C33.2339 11.4025 30.7368 9.84189 28.6015 10.8973Z\" fill=\"currentColor\" fillOpacity={0.7} />\n      </svg>\n    </span>\n  );\n}\n\n/** The app around the page: the sidebar (a drawer where it doesn't fit), and the page on a panel under its header, with room on the panel for an inspector. */\nfunction AppFrame({ page, crumbs, actions, panel, children }: { page: string; crumbs: string[]; actions?: ReactNode; panel?: ReactNode; children: ReactNode }) {\n  const [mode, setMode] = useState<\"side\" | \"drawer\">(\"side\");\n  const [open, setOpen] = useState(false);\n  return (\n    <div className=\"@container relative flex h-full min-h-0 bg-[var(--bd-well)] text-[var(--bd-fg)]\">\n      <AppSidebar\n        plain\n        contained\n        breakpoint={900}\n        sections={SECTIONS}\n        views={VIEWS}\n        active={page}\n        workspaces={[\n          { id: \"acme\", name: \"Acme\", plan: \"Team\", logo: <Mark /> },\n          { id: \"personal\", name: \"Personal\", plan: \"Hobby\" },\n        ]}\n        defaultWorkspace=\"acme\"\n        footer={(rail) => <Allowance label=\"Build minutes\" used={5046} limit={6000} projected={6210} note=\"Renews Nov 30\" compact={rail} className={rail ? \"mx-auto\" : undefined} />}\n        account={(rail) => (\n          <AccountMenu\n            user={{ name: \"Emily Carter\", email: \"emily@acme.com\" }}\n            trigger={rail ? \"face\" : \"row\"}\n            defaultNote=\"Planning the fourth quarter\"\n            workspaces={[\n              { id: \"acme\", name: \"Acme\", role: \"Owner\", logo: <Mark /> },\n              { id: \"personal\", name: \"Personal\", role: \"Hobby\" },\n            ]}\n            workspace=\"acme\"\n            onPreferences={() => undefined}\n            onSignOut={() => undefined}\n          />\n        )}\n        onSearch={() => undefined}\n        open={open}\n        onOpenChange={setOpen}\n        onModeChange={setMode}\n      />\n      <div className=\"flex min-w-0 flex-1 flex-col @3xl:py-2 @3xl:pr-2\">\n        <main className=\"@container/main relative flex min-h-0 flex-1 flex-col overflow-hidden bg-[var(--bd-surface)] @3xl:rounded-[14px] @3xl:shadow-[0_0_0_1px_var(--bd-line-subtle),0_1px_3px_rgb(var(--bd-shade)/0.06)]\">\n          <header className=\"flex h-12 shrink-0 items-center gap-2 border-b border-[var(--bd-line-subtle)] px-3 @3xl:px-5\">\n            {mode === \"drawer\" && (\n              <button type=\"button\" onClick={() => setOpen(true)} aria-label=\"Open the menu\" className=\"grid size-8 place-items-center rounded-full text-[var(--bd-muted)] hover:bg-[rgb(var(--bd-ink)/0.06)]\">\n                <ListIcon weight=\"regular\" size={17} />\n              </button>\n            )}\n            <span className=\"min-w-0 @max-xl:hidden\">\n              <Breadcrumb items={crumbs.map((label, i) => (i < crumbs.length - 1 ? { label, href: `/${crumbs.slice(0, i + 1).join(\"/\").toLowerCase()}` } : { label }))} />\n            </span>\n            {/* Where there's no room for the trail, the page's name alone. */}\n            <span className=\"truncate text-[13.5px] font-medium @xl:hidden\">{crumbs.at(-1)}</span>\n            <div className=\"ml-auto flex items-center gap-2\">{actions}</div>\n          </header>\n          {/* The page, and beside it what's opened from it, which pushes the page left as it opens. */}\n          <div className=\"relative flex min-h-0 flex-1\">\n            {/* It scrolls without a bar, the way an app's page does. */}\n            <div className=\"relative min-h-0 min-w-0 flex-1 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden\">{children}</div>\n            {panel}\n          </div>\n        </main>\n      </div>\n    </div>\n  );\n}\n\ntype Env = \"production\" | \"preview\";\ntype State = \"building\" | \"ready\" | \"error\" | \"canceled\";\ntype StageId = \"queue\" | \"install\" | \"build\" | \"checks\" | \"domains\";\n\ntype Deploy = {\n  id: string;\n  sha: string;\n  message: string;\n  branch: string;\n  author: string;\n  env: Env;\n  state: State;\n  /** How long it ran, start to end. */\n  took: number;\n  when: string;\n  day: string;\n  /** How long each stage took, once a build watched here is over. */\n  times?: number[];\n  /** Where it stopped, and what it said there: a failed stage, or the one it was canceled in. */\n  stopped?: { stage: StageId; note?: string; log?: Array<[string, \"info\" | \"warn\" | \"error\"]> };\n};\n\n/* The stages every deployment goes through, and the share of its time each usually takes. */\nconst STAGES: Array<{ id: StageId; label: string; share: number; note?: string }> = [\n  { id: \"queue\", label: \"Queued\", share: 0.04 },\n  { id: \"install\", label: \"Install\", share: 0.36, note: \"1,204 packages\" },\n  { id: \"build\", label: \"Build\", share: 0.42, note: \"38 pages\" },\n  { id: \"checks\", label: \"Checks\", share: 0.14, note: \"214 tests\" },\n  { id: \"domains\", label: \"Domains\", share: 0.04 },\n];\n\nconst PRODUCTION = [\"acme.com\", \"www.acme.com\", \"storefront-acme.relay.app\"];\nconst domainsOf = (d: Deploy) => (d.env === \"production\" ? PRODUCTION : [`storefront-git-${d.branch.replace(/[^a-z0-9]+/gi, \"-\").toLowerCase()}-acme.relay.app`]);\n\nconst DEPLOYS: Deploy[] = [\n  { id: \"dpl_7c2e\", sha: \"7c2e9a14b0d3e5f8a91c2d4e6f7a8b9c0d1e2f30\", message: \"Gift card balance at checkout\", branch: \"feat/gift-cards\", author: \"Sarah Mitchell\", env: \"preview\", state: \"building\", took: 0, when: \"just now\", day: \"Today\" },\n  { id: \"dpl_a1f9\", sha: \"a1f9c2e47b0d3e5f8a91c2d4e6f7a8b9c0d1e2f3\", message: \"Round cart totals once, at checkout\", branch: \"main\", author: \"Jake Morrison\", env: \"production\", state: \"ready\", took: 52000, when: \"2h ago\", day: \"Today\" },\n  { id: \"dpl_9c0d\", sha: \"9c0d1e2f3a4b5c6d7e8f9a0b1c2d3e4f5a6b7c8d\", message: \"Search that forgives typos\", branch: \"feat/search\", author: \"Megan Turner\", env: \"preview\", state: \"ready\", took: 47000, when: \"3h ago\", day: \"Today\" },\n  {\n    id: \"dpl_4b8e\",\n    sha: \"4b8e0f3a9c2d1e7f6a5b4c3d2e1f0a9b8c7d6e5f\",\n    message: \"Cache product pages by region\",\n    branch: \"fix/edge-cache\",\n    author: \"Ryan Brooks\",\n    env: \"preview\",\n    state: \"error\",\n    took: 63000,\n    when: \"5h ago\",\n    day: \"Today\",\n    stopped: {\n      stage: \"checks\",\n      note: \"2 type errors\",\n      log: [\n        [\"Running type check\", \"info\"],\n        [\"src/lib/cache.ts(42,7): Argument of type 'Region | undefined' is not assignable to parameter of type 'Region'.\", \"error\"],\n        [\"src/app/products/[slug]/page.tsx(18,21): Property 'region' does not exist on type 'Headers'.\", \"error\"],\n        [\"Found 2 errors. Stopping before the deploy.\", \"warn\"],\n      ],\n    },\n  },\n  { id: \"dpl_2e7d\", sha: \"2e7d9c4b1a0f8e7d6c5b4a3f2e1d0c9b8a7f6e5d\", message: \"Typo tolerance behind a flag\", branch: \"feat/search\", author: \"Megan Turner\", env: \"preview\", state: \"canceled\", took: 14000, when: \"6h ago\", day: \"Today\", stopped: { stage: \"install\", note: \"Newer push to feat/search\" } },\n  { id: \"dpl_8f3a\", sha: \"8f3a2b1c0d9e8f7a6b5c4d3e2f1a0b9c8d7e6f5a\", message: \"Resize product images at the edge\", branch: \"main\", author: \"Tyler Hayes\", env: \"production\", state: \"ready\", took: 58000, when: \"4:12 PM\", day: \"Yesterday\" },\n  { id: \"dpl_1d4c\", sha: \"1d4c6e8f0a2b4c6d8e0f2a4b6c8d0e2f4a6b8c0d\", message: \"Referral credits on the account page\", branch: \"feat/referrals\", author: \"Lauren Price\", env: \"preview\", state: \"ready\", took: 44000, when: \"2:40 PM\", day: \"Yesterday\" },\n  { id: \"dpl_6b2f\", sha: \"6b2f9d0e1c2b3a4f5e6d7c8b9a0f1e2d3c4b5a6f\", message: \"Schedule the holiday banner\", branch: \"main\", author: \"Emily Carter\", env: \"production\", state: \"ready\", took: 51000, when: \"10:05 AM\", day: \"Yesterday\" },\n  {\n    id: \"dpl_5c1b\",\n    sha: \"5c1b8e2d3f4a5b6c7d8e9f0a1b2c3d4e5f6a7b8c\",\n    message: \"Upgrade to Next 16.4\",\n    branch: \"main\",\n    author: \"Ryan Brooks\",\n    env: \"production\",\n    state: \"error\",\n    took: 38000,\n    when: \"Oct 28\",\n    day: \"Oct 28\",\n    stopped: {\n      stage: \"build\",\n      note: \"Module not found: sharp\",\n      log: [\n        ['Running \"next build\"', \"info\"],\n        [\"Creating an optimized production build\", \"info\"],\n        [\"Module not found: Can't resolve 'sharp' in node_modules/next/dist/server/image-optimizer.js\", \"error\"],\n        [\"Build failed. Production still serves 3e9a7c5.\", \"warn\"],\n      ],\n    },\n  },\n  { id: \"dpl_3e9a\", sha: \"3e9a7c5b4d2e1f0a9b8c7d6e5f4a3b2c1d0e9f8a\", message: \"Tax on shipping in Colorado\", branch: \"main\", author: \"Jake Morrison\", env: \"production\", state: \"ready\", took: 49000, when: \"Oct 28\", day: \"Oct 28\" },\n];\n\n/* The push building as the page opens: its stages' lengths, and how far in it is. */\nconst LIVE_PLAN = [2000, 17000, 14000, 6000, 2000];\nconst LIVE_HEAD = 24000;\nconst PRODUCTION_PLAN = [2000, 15000, 13000, 6000, 2000];\n\n/* What each stage says, line by line, for a deploy. */\nfunction lines(d: Deploy, stage: StageId): Array<[string, \"info\" | \"warn\" | \"error\"]> {\n  if (d.stopped?.stage === stage && d.stopped.log) return d.stopped.log;\n  const sha = d.sha.slice(0, 7);\n  switch (stage) {\n    case \"queue\":\n      return [[\"Queued for a build machine in iad1\", \"info\"], [\"Picked up: 4 cores, 8 GB\", \"info\"]];\n    case \"install\":\n      return [[`Cloning github.com/acme/storefront (branch ${d.branch}, commit ${sha})`, \"info\"], [\"Restored the build cache from the last deployment\", \"info\"], ['Running \"npm install\"', \"info\"], [\"added 1,204 packages in 9s\", \"info\"]];\n    case \"build\":\n      return [['Running \"next build\"', \"info\"], [\"Creating an optimized production build\", \"info\"], [\"Compiled successfully in 14.2s\", \"info\"], [\"Generating static pages (38/38)\", \"info\"], [\"Finalizing page optimization\", \"info\"]];\n    case \"checks\":\n      return [[\"Running type check\", \"info\"], [\"Running 214 tests in 4 workers\", \"info\"], [\"214 passed\", \"info\"]];\n    case \"domains\":\n      return [...domainsOf(d).map((u): [string, \"info\"] => [`Assigned ${u}`, \"info\"]), [\"Ready\", \"info\"]];\n  }\n}\n\n/* The times on the log lines: one fixed afternoon, so the page reads the same on the server and in the browser. */\nconst T0 = Date.UTC(2026, 9, 31, 14, 32, 0);\n\n/** A deployment's stages: from its clock while it runs, from how long it took once it's over. */\nfunction stagesOf(d: Deploy, live: { elapsed: number; plan: number[] } | null): PipelineStage[] {\n  if (live) {\n    let start = 0;\n    return STAGES.map((s, i) => {\n      const from = start;\n      start += live.plan[i];\n      const status: PipelineStatus = live.elapsed >= start ? \"done\" : live.elapsed >= from ? \"running\" : \"waiting\";\n      return { id: s.id, label: s.label, status, duration: status === \"done\" ? live.plan[i] : status === \"running\" ? live.elapsed - from : undefined, estimate: status === \"done\" ? undefined : live.plan[i], note: status === \"done\" ? s.note : undefined };\n    });\n  }\n  const stopAt = d.stopped ? STAGES.findIndex((s) => s.id === d.stopped!.stage) : -1;\n  return STAGES.map((s, i) => {\n    const ms = d.times?.[i] ?? Math.max(1000, Math.round((d.took * s.share) / 1000) * 1000);\n    if (stopAt < 0) return { id: s.id, label: s.label, status: \"done\", duration: ms, note: s.note };\n    if (i < stopAt) return { id: s.id, label: s.label, status: \"done\", duration: ms, note: s.note };\n    if (i === stopAt) return { id: s.id, label: s.label, status: d.state === \"error\" ? \"failed\" : \"canceled\", duration: ms, note: d.stopped!.note };\n    return { id: s.id, label: s.label, status: \"skipped\" };\n  });\n}\n\n/** A stage's log: as much of it as the stage has reached (while it builds, by the build's plan). */\nfunction logOf(d: Deploy, stage: PipelineStage | undefined, plan?: number[]): LogLine[] {\n  if (!stage || stage.status === \"waiting\" || stage.status === \"skipped\") return [];\n  const all = lines(d, stage.id as StageId);\n  const at = STAGES.findIndex((s) => s.id === stage.id);\n  const base = T0 + at * 9000;\n  // Running, it has said as many of its lines as its share of time so far allows.\n  const length = plan?.[at] ?? d.times?.[at] ?? Math.max(1000, d.took * STAGES[at].share);\n  const shown = stage.status === \"running\" ? Math.max(1, Math.min(all.length - 1, Math.floor(((stage.duration ?? 0) / length) * all.length) + 1)) : all.length;\n  return all.slice(0, shown).map(([message, level], i) => ({ id: `${stage.id}-${i}`, time: base + i * 1300, level, message }));\n}\n\nconst LOOK: Record<State, { dot: string; word: string }> = {\n  ready: { dot: \"bg-[var(--bd-ui-ok)]\", word: \"Ready\" },\n  building: { dot: \"bg-[var(--bd-ui-wait)]\", word: \"Building\" },\n  error: { dot: \"bg-[var(--bd-ui-stop)]\", word: \"Error\" },\n  canceled: { dot: \"bg-[rgb(var(--bd-ink)/0.28)]\", word: \"Canceled\" },\n};\n\n/** A deployment's state: a dot and its word. The dot breathes while it builds. */\nfunction Status({ state, className }: { state: State; className?: string }) {\n  const still = useReducedMotion();\n  return (\n    <span className={`inline-flex items-center gap-2 text-[13px] ${state === \"ready\" ? \"text-[var(--bd-fg)]\" : state === \"canceled\" ? \"text-[var(--bd-muted)]\" : \"text-[var(--bd-fg)]\"} ${className ?? \"\"}`}>\n      <span className=\"relative grid size-2 shrink-0 place-items-center\">\n        {state === \"building\" && !still && <motion.span className={`absolute inset-0 rounded-full ${LOOK[state].dot}`} animate={{ scale: [1, 2.4], opacity: [0.5, 0] }} transition={{ duration: 1.4, repeat: Infinity, ease: \"easeOut\" }} />}\n        <span className={`relative size-2 rounded-full ${LOOK[state].dot}`} />\n      </span>\n      {LOOK[state].word}\n    </span>\n  );\n}\n\n/** Production's own mark: an ink tag on the one deployment that's live. */\nconst Current = () => <span className=\"inline-flex h-5 items-center rounded-full px-2 text-[11px] font-medium text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.14)]\">Current</span>;\n\nconst FIELDS: FilterField[] = [\n  { id: \"env\", label: \"Environment\", icon: <GlobeSimpleIcon weight=\"duotone\" />, plural: \"environments\", options: [{ value: \"production\", label: \"Production\" }, { value: \"preview\", label: \"Preview\" }] },\n  { id: \"state\", label: \"Status\", icon: <CircleHalfIcon weight=\"duotone\" />, plural: \"statuses\", options: (Object.keys(LOOK) as State[]).map((s) => ({ value: s, label: LOOK[s].word })) },\n  { id: \"branch\", label: \"Branch\", icon: <GitBranchIcon weight=\"duotone\" />, plural: \"branches\", options: [...new Set(DEPLOYS.map((d) => d.branch))].map((b) => ({ value: b, label: b })) },\n  { id: \"author\", label: \"Author\", icon: <UserIcon weight=\"duotone\" />, plural: \"people\", options: [...new Set(DEPLOYS.map((d) => d.author))].map((a) => ({ value: a, label: a })) },\n];\n\n/* In your app, Visit opens the deployment; here it says where it would go. */\nconst visit = (url: string) => toast(`Opening ${url}`, { description: \"In your app this opens in a new tab.\" });\nconst copyUrl = (url: string) => void navigator.clipboard?.writeText(`https://${url}`).then(() => toast(\"Link copied\", { description: `https://${url}` }));\n\n/** What a deployment is and where it went: its environment, and the Current tag on the live one. */\nfunction Where({ d, current }: { d: Deploy; current: boolean }) {\n  return (\n    <span className=\"flex min-w-0 items-center gap-2 text-[13px]\">\n      <span className={d.env === \"production\" ? \"text-[var(--bd-fg)]\" : \"text-[var(--bd-muted)]\"}>{d.env === \"production\" ? \"Production\" : \"Preview\"}</span>\n      {current && <Current />}\n    </span>\n  );\n}\n/** A quiet button that copies an address, with a check for a moment once it has. */\nfunction CopyAddress({ url }: { url: string }) {\n  const [done, setDone] = useState(false);\n  useEffect(() => {\n    if (!done) return;\n    const t = window.setTimeout(() => setDone(false), 1400);\n    return () => window.clearTimeout(t);\n  }, [done]);\n  return (\n    <button\n      type=\"button\"\n      onClick={() => void navigator.clipboard?.writeText(`https://${url}`).then(() => setDone(true))}\n      aria-label={done ? \"Copied\" : `Copy ${url}`}\n      className=\"grid size-8 place-items-center rounded-full text-[var(--bd-muted)] transition-colors hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\"\n    >\n      {done ? <CheckIcon weight=\"bold\" className=\"size-3.5 text-[var(--bd-fg)]\" /> : <CopyIcon weight=\"regular\" className=\"size-3.5\" />}\n    </button>\n  );\n}\n\n/** What each address is, and its mark: the one people type, the one that sends to it, and the platform's own. */\nfunction roleOf(d: Deploy, url: string) {\n  if (d.env === \"preview\") return { word: \"Preview address\", primary: false, Icon: EyeIcon };\n  if (url === \"acme.com\") return { word: \"Primary\", primary: true, Icon: GlobeSimpleIcon };\n  if (url.startsWith(\"www.\")) return { word: \"Redirects to acme.com\", primary: false, Icon: ArrowBendDownRightIcon };\n  return { word: \"relay.app address\", primary: false, Icon: LinkSimpleIcon };\n}\n\n/** Under a small title, a list ruled by hairlines: the shape both columns of the details share. */\nfunction Ruled({ title, list = false, children }: { title: string; /** A list of terms and what they are (a dl), rather than plain rows. */ list?: boolean; children: ReactNode }) {\n  const Rows = list ? \"dl\" : \"div\";\n  return (\n    <section aria-label={title} className=\"min-w-0\">\n      <h3 className=\"pb-2 text-[12px] font-medium text-[var(--bd-muted)]\">{title}</h3>\n      <Rows className=\"divide-y divide-[var(--bd-line-subtle)] border-y border-[var(--bd-line-subtle)]\">{children}</Rows>\n    </section>\n  );\n}\n\n/** A deployment's domains: each address, what it is, and (on a pointer, as it passes) copy and open. */\nfunction Domains({ d }: { d: Deploy }) {\n  return (\n    <Ruled title=\"Domains\">\n      {domainsOf(d).map((u) => {\n        const role = roleOf(d, u);\n        return (\n          <div key={u} className=\"group/domain flex h-11 min-w-0 items-center gap-3\">\n            <role.Icon weight=\"duotone\" aria-hidden className=\"size-4 shrink-0 text-[var(--bd-subtle)]\" />\n            <span className=\"min-w-0 truncate font-mono text-[13px] text-[var(--bd-fg)]\">{u}</span>\n            {role.primary ? (\n              <span className=\"inline-flex h-5 shrink-0 items-center rounded-full px-2 text-[11px] font-medium shadow-[inset_0_0_0_1px_var(--bd-line-strong)]\">{role.word}</span>\n            ) : (\n              <span className=\"shrink-0 truncate text-[12px] text-[var(--bd-subtle)] @max-md:hidden\">{role.word}</span>\n            )}\n            <span className=\"ml-auto flex shrink-0 items-center transition-opacity [@media(hover:hover)]:opacity-0 group-hover/domain:opacity-100 group-focus-within/domain:opacity-100\">\n              <CopyAddress url={u} />\n              <button type=\"button\" onClick={() => visit(u)} aria-label={`Open ${u}`} className=\"grid size-8 place-items-center rounded-full text-[var(--bd-muted)] transition-colors hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\">\n                <ArrowUpRightIcon weight=\"regular\" className=\"size-3.5\" />\n              </button>\n            </span>\n          </div>\n        );\n      })}\n    </Ruled>\n  );\n}\n\n/** What's live, as a short spec: how it was built, when and by whom, and where it runs. */\nfunction Facts({ d }: { d: Deploy }) {\n  const rows: Array<[typeof TimerIcon, string, string, string]> = [\n    [TimerIcon, \"Built in\", formatDuration(d.took), d.times ? \"Watched here, stage by stage\" : \"4 cores in iad1\"],\n    [RocketLaunchIcon, \"Deployed\", d.when, `By ${d.author}`],\n    [GlobeHemisphereWestIcon, \"Regions\", \"iad1, fra1\", \"Washington, D.C. and Frankfurt\"],\n  ];\n  return (\n    <Ruled title=\"Deployment\" list>\n      {rows.map(([Icon, k, v, sub]) => (\n        <div key={k} className=\"grid min-h-11 grid-cols-[120px_minmax(0,1fr)] items-baseline gap-4 py-2.5\">\n          <dt className=\"flex items-center gap-3 self-start pt-px text-[12.5px] text-[var(--bd-muted)]\">\n            <Icon weight=\"duotone\" aria-hidden className=\"size-4 shrink-0 text-[var(--bd-subtle)]\" />\n            {k}\n          </dt>\n          <dd className=\"min-w-0\">\n            <span className=\"block truncate text-[13.5px] font-medium tabular-nums text-[var(--bd-fg)]\">{v}</span>\n            <span className=\"mt-0.5 block truncate text-[12px] text-[var(--bd-subtle)]\">{sub}</span>\n          </dd>\n        </div>\n      ))}\n    </Ruled>\n  );\n}\n\ntype Acts = { promote: (d: Deploy) => void; rollback: (d: Deploy) => void; redeploy: (d: Deploy, clean?: boolean) => void; cancel: () => void; inspect: (d: Deploy) => void };\n\n/** What a deployment can do, by where it's at, in its row's menu. */\nfunction RowMenu({ d, current, acts }: { d: Deploy; current: boolean; acts: Acts }) {\n  const url = domainsOf(d)[0];\n  return (\n    <Menu>\n      <MenuTrigger aria-label={`More for ${d.message}`} className=\"relative z-10 grid size-8 place-items-center rounded-full text-[var(--bd-muted)] transition-colors hover:bg-[rgb(var(--bd-ink)/0.07)] hover:text-[var(--bd-fg)] aria-expanded:bg-[rgb(var(--bd-ink)/0.07)]\">\n        <DotsThreeIcon weight=\"bold\" className=\"size-4\" />\n      </MenuTrigger>\n      <MenuContent align=\"end\">\n        {d.state === \"ready\" && (\n          <MenuItem icon={<ArrowUpRightIcon weight=\"regular\" />} onSelect={() => visit(url)}>\n            Visit\n          </MenuItem>\n        )}\n        <MenuItem icon={<LinkSimpleIcon weight=\"duotone\" />} onSelect={() => copyUrl(url)}>\n          Copy its address\n        </MenuItem>\n        <MenuItem icon={<MagnifyingGlassIcon weight=\"duotone\" />} onSelect={() => acts.inspect(d)}>\n          Inspect\n        </MenuItem>\n        <MenuSeparator />\n        {d.state === \"ready\" && d.env === \"preview\" && (\n          <MenuItem icon={<RocketLaunchIcon weight=\"duotone\" />} onSelect={() => acts.promote(d)}>\n            Promote to production\n          </MenuItem>\n        )}\n        {d.state === \"ready\" && d.env === \"production\" && !current && (\n          <MenuItem icon={<ArrowCounterClockwiseIcon weight=\"regular\" />} onSelect={() => acts.rollback(d)}>\n            Roll back to this\n          </MenuItem>\n        )}\n        {d.state === \"building\" ? (\n          <MenuItem tone=\"stop\" icon={<ProhibitIcon weight=\"duotone\" />} onSelect={acts.cancel}>\n            Cancel the build\n          </MenuItem>\n        ) : (\n          <MenuItem icon={<ArrowClockwiseIcon weight=\"regular\" />} onSelect={() => acts.redeploy(d)}>\n            Redeploy\n          </MenuItem>\n        )}\n      </MenuContent>\n    </Menu>\n  );\n}\n\n/**\n * One deployment, one row: its state, where it went, its commit, how long it took and when, and\n * its menu. The whole row opens it; the hash and the menu work on their own. In a narrow list it\n * folds onto two lines.\n */\nfunction Row({ d, current, open, live, acts }: { d: Deploy; current: boolean; open: boolean; live: number | null; acts: Acts }) {\n  const took = d.state === \"building\" ? (live != null ? formatDuration(live) : \"\") : formatDuration(d.took);\n  return (\n    <li className={`group/row relative rounded-[12px] transition-colors ${open ? \"bg-[rgb(var(--bd-ink)/0.055)]\" : \"hover:bg-[rgb(var(--bd-ink)/0.03)]\"}`}>\n      {/* The press that opens it, under everything else in the row. */}\n      <button type=\"button\" onClick={() => acts.inspect(d)} aria-label={`Open ${d.message}`} aria-expanded={open} className=\"absolute inset-0 cursor-pointer rounded-[12px] outline-none focus-visible:shadow-[0_0_0_2px_var(--bd-ui-focus)]\" />\n      {/* Wide: one line, in columns that line up down the list. */}\n      <div className=\"pointer-events-none relative hidden h-12 grid-cols-[100px_150px_minmax(0,1fr)_64px_72px_32px] items-center gap-4 px-3 @4xl/list:grid\">\n        <Status state={d.state} />\n        <Where d={d} current={current} />\n        {/* Only the hash takes a press of its own here; the rest of the commit opens the row. */}\n        <div className=\"min-w-0 [&_button]:pointer-events-auto\">\n          <Commit message={d.message} sha={d.sha} branch={d.branch} author={d.author} />\n        </div>\n        <span className=\"text-right font-mono text-[12px] tabular-nums text-[var(--bd-muted)]\">{took}</span>\n        <span className=\"truncate text-right text-[12.5px] tabular-nums text-[var(--bd-subtle)]\">{d.when}</span>\n        <span className=\"pointer-events-auto\">\n          <RowMenu d={d} current={current} acts={acts} />\n        </span>\n      </div>\n      {/* Narrow: the message on top, the rest under it. */}\n      <div className=\"pointer-events-none relative flex items-center gap-3 px-3 py-2.5 @4xl/list:hidden\">\n        <span className={`size-2 shrink-0 rounded-full ${LOOK[d.state].dot}`} aria-hidden />\n        <span className=\"min-w-0 flex-1\">\n          <span className=\"flex items-center gap-2\">\n            <span className=\"min-w-0 flex-1 truncate text-[13.5px] font-medium\">{d.message}</span>\n            <span className=\"shrink-0 text-[12px] tabular-nums text-[var(--bd-subtle)]\">{d.when}</span>\n          </span>\n          <span className=\"mt-0.5 flex items-center gap-1.5 text-[12px] text-[var(--bd-muted)]\">\n            <span className=\"sr-only\">{LOOK[d.state].word}, </span>\n            {d.env === \"production\" ? \"Production\" : \"Preview\"}\n            {current && <span className=\"font-medium text-[var(--bd-fg)]\">· Current</span>}\n            <span className=\"truncate font-mono\">· {d.branch}</span>\n            {took && <span className=\"font-mono tabular-nums\">· {took}</span>}\n          </span>\n        </span>\n        <span className=\"pointer-events-auto\">\n          <RowMenu d={d} current={current} acts={acts} />\n        </span>\n      </div>\n    </li>\n  );\n}\n\n/**\n * A deployment opened, over the right of the page: what it is, its stages (a failed one opens on\n * where it failed), the picked stage's log, its domains, and at its foot what it can do now.\n */\nfunction Inspector({ d, stages, plan, current, live, acts, onClose }: { d: Deploy; stages: PipelineStage[]; plan?: number[]; current: boolean; live: boolean; acts: Acts; onClose: () => void }) {\n  const head = useRef<HTMLHeadingElement>(null);\n  const stoppedAt = d.stopped?.stage;\n  const [picked, setPicked] = useState<string | null>(null);\n  const running = stages.find((s) => s.status === \"running\")?.id;\n  const stage = picked ?? stoppedAt ?? running ?? \"domains\";\n  const shown = stages.find((s) => s.id === stage);\n  useEffect(() => head.current?.focus({ preventScroll: true }), []);\n  const after = (fn: () => void) => () => window.setTimeout(fn, 650);\n  return (\n    <motion.div\n      aria-labelledby=\"deploy-title\"\n      initial={{ opacity: 0 }}\n      animate={{ opacity: 1 }}\n      transition={{ duration: 0.2 }}\n      onKeyDown={(e) => {\n        if (e.key === \"Escape\" && !e.defaultPrevented) {\n          e.preventDefault();\n          onClose();\n        }\n      }}\n      className=\"flex h-full min-h-0 flex-col\"\n    >\n      <header className=\"flex items-center gap-3 border-b border-[var(--bd-line-subtle)] px-5 py-3.5\">\n        <Status state={d.state} />\n        <span className=\"h-4 w-px bg-[var(--bd-line)]\" />\n        <Where d={d} current={current} />\n        <button type=\"button\" onClick={onClose} aria-label=\"Close\" className=\"-mr-1.5 ml-auto grid size-8 place-items-center rounded-full text-[var(--bd-muted)] hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\">\n          <XIcon weight=\"regular\" className=\"size-4\" />\n        </button>\n      </header>\n      <div className=\"min-h-0 flex-1 overflow-y-auto px-5 pb-6 pt-5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden\">\n        <h2 id=\"deploy-title\" ref={head} tabIndex={-1} className=\"sr-only\">\n          {d.message}\n        </h2>\n        <Commit layout=\"stack\" message={d.message} sha={d.sha} branch={d.branch} author={d.author} time={d.when} />\n        <div className=\"mt-6\">\n          <Pipeline label={`Stages of ${d.sha.slice(0, 7)}`} stages={stages} selected={stage} onSelect={setPicked} />\n        </div>\n        <div className=\"mt-4\">\n          <LogViewer key={stage} title={shown?.label ?? \"Log\"} lines={logOf(d, shown, plan)} live={live && shown?.status === \"running\"} height={300} wrap />\n        </div>\n        {d.state === \"ready\" && (\n          <div className=\"mt-7\">\n            <Domains d={d} />\n          </div>\n        )}\n      </div>\n      {/* What it can do now, at its foot. */}\n      <footer className=\"flex flex-wrap items-center justify-end gap-2 border-t border-[var(--bd-line-subtle)] px-5 py-3\">\n        {d.state === \"building\" && (\n          <Button variant=\"outline\" size=\"sm\" onClick={acts.cancel}>\n            <ProhibitIcon weight=\"duotone\" /> Cancel the build\n          </Button>\n        )}\n        {d.state === \"ready\" && (\n          <Button variant=\"ghost\" size=\"sm\" onClick={() => visit(domainsOf(d)[0])}>\n            Visit <ArrowUpRightIcon weight=\"regular\" />\n          </Button>\n        )}\n        {d.state === \"ready\" && d.env === \"preview\" && (\n          <HoldButton done=\"Promoted\" icon={<RocketLaunchIcon weight=\"duotone\" />} onConfirm={after(() => acts.promote(d))}>\n            Hold to promote\n          </HoldButton>\n        )}\n        {d.state === \"ready\" && d.env === \"production\" && !current && (\n          <HoldButton done=\"Rolled back\" icon={<ArrowCounterClockwiseIcon weight=\"regular\" />} onConfirm={after(() => acts.rollback(d))}>\n            Hold to roll back\n          </HoldButton>\n        )}\n        {(d.state !== \"building\" && (d.state !== \"ready\" || current)) && (\n          <Button variant=\"outline\" size=\"sm\" onClick={() => acts.redeploy(d)}>\n            <ArrowClockwiseIcon weight=\"regular\" /> Redeploy\n          </Button>\n        )}\n      </footer>\n    </motion.div>\n  );\n}\n\n/* The side panel's width, open. */\nconst SIDE = 440;\n\n/**\n * Where an opened deployment shows, at the page's right. It opens by widening from nothing, so on a\n * wide screen the page eases left to make room, and on a narrow one, with no room to share, it lies\n * over the page instead. What's in it keeps its full width throughout, held to the right, so it\n * slides in rather than squeezes.\n */\nfunction Side({ label, children }: { label: string; children: ReactNode }) {\n  const still = useReducedMotion();\n  return (\n    <motion.aside\n      aria-label={label}\n      initial={{ width: 0 }}\n      animate={{ width: SIDE }}\n      exit={{ width: 0 }}\n      transition={still ? { duration: 0 } : { type: \"spring\", stiffness: 340, damping: 40, mass: 0.9 }}\n      className=\"relative h-full max-w-full shrink-0 overflow-hidden border-l border-[var(--bd-line-subtle)] bg-[var(--bd-surface)] @max-4xl/main:absolute @max-4xl/main:inset-y-0 @max-4xl/main:right-0 @max-4xl/main:z-20 @max-4xl/main:border-l-0 @max-4xl/main:shadow-[0_0_0_1px_rgb(var(--bd-ink)/0.08),-24px_0_48px_-24px_rgb(var(--bd-shade)/0.4)]\"\n    >\n      <div className=\"absolute inset-y-0 right-0 w-[min(440px,100cqw)]\">{children}</div>\n    </motion.aside>\n  );\n}\n\n/**\n * The lead. While a push builds: what it is, its time so far, its stages turning over, and the\n * running stage's last lines; once it's ready, a hold to promote it. With nothing in flight: what\n * production serves, where, and a hold to roll back to what was live before.\n */\nfunction Lead({ d, stages, plan, elapsed, live, current, previous, acts }: { d: Deploy; stages: PipelineStage[]; plan?: number[]; elapsed: number; live: boolean; current: boolean; previous?: Deploy; acts: Acts }) {\n  const running = stages.find((s) => s.status === \"running\");\n  const [picked, setPicked] = useState<string | null>(null);\n  const stage = stages.find((s) => s.id === (picked ?? running?.id ?? \"domains\"));\n  const tail = logOf(d, stage, plan).slice(-4);\n  const ready = d.state === \"ready\";\n  const after = (fn: () => void) => () => window.setTimeout(fn, 650);\n  const word = live ? (ready ? `${d.env === \"production\" ? \"Production\" : \"Preview\"} ready in ${formatDuration(d.took)}` : `Building ${d.env === \"production\" ? \"for production\" : \"a preview\"}`) : \"Live in production\";\n  return (\n    <section aria-labelledby=\"lead-title\" className=\"rounded-[22px] bg-[var(--bd-surface)] p-5 shadow-[0_0_0_1px_rgb(var(--bd-ink)/0.08),0_1px_2px_rgb(var(--bd-shade)/0.05),0_16px_40px_-24px_rgb(var(--bd-shade)/0.35)] @2xl:p-7\">\n      {/* The head: what it is on the left, what can be done with it at the top right. */}\n      <div className=\"flex flex-wrap items-start justify-between gap-x-10 gap-y-5\">\n        <div className=\"min-w-0 flex-1 basis-[360px]\">\n          <p id=\"lead-title\" className=\"flex items-center gap-2 text-[12.5px] font-medium text-[var(--bd-muted)]\">\n            <Status state={d.state} className=\"sr-only\" />\n            <span className={`size-2 rounded-full ${LOOK[d.state].dot}`} aria-hidden />\n            {word}\n          </p>\n          <div className=\"mt-3\">\n            <Commit layout=\"stack\" size=\"lg\" message={d.message} sha={d.sha} branch={d.branch} author={d.author} time={live && !ready ? \"pushed just now\" : d.when} />\n          </div>\n        </div>\n        {/* Its clock while it builds; what it can do once it's done. */}\n        <div className=\"-mt-1 flex shrink-0 items-center gap-2\">\n          {live && !ready ? (\n            <>\n              <span className=\"mr-3 font-mono text-[28px] font-medium tabular-nums tracking-[-0.03em]\" aria-label={`${formatDuration(elapsed)} so far`}>\n                {formatDuration(elapsed)}\n              </span>\n              <Button variant=\"outline\" size=\"sm\" onClick={acts.cancel}>\n                Cancel\n              </Button>\n            </>\n          ) : (\n            <>\n              <Button variant=\"ghost\" size=\"sm\" onClick={() => visit(domainsOf(d)[0])}>\n                Visit <ArrowUpRightIcon weight=\"regular\" />\n              </Button>\n              {live && ready && d.env === \"preview\" && (\n                <HoldButton done=\"Promoted\" icon={<RocketLaunchIcon weight=\"duotone\" />} onConfirm={after(() => acts.promote(d))}>\n                  Hold to promote\n                </HoldButton>\n              )}\n              {!live && current && previous && (\n                <HoldButton done=\"Rolled back\" icon={<ArrowCounterClockwiseIcon weight=\"regular\" />} onConfirm={after(() => acts.rollback(previous))}>\n                  Hold to roll back\n                </HoldButton>\n              )}\n            </>\n          )}\n        </div>\n      </div>\n      {/* Where a preview is served, in a bar of its own: where it will be while it builds, and once it's ready, to copy or open. */}\n      {live && d.env === \"preview\" && (\n        <div className=\"mt-6 flex h-11 min-w-0 items-center gap-3 rounded-[12px] bg-[var(--bd-ui-field)] pl-3.5 pr-1.5 shadow-[var(--bd-ui-well)]\">\n          <GlobeSimpleIcon weight=\"duotone\" aria-hidden className=\"size-4 shrink-0 text-[var(--bd-subtle)]\" />\n          <span className=\"shrink-0 text-[12.5px] text-[var(--bd-muted)]\">{ready ? \"Preview\" : \"Will be at\"}</span>\n          <span className={`min-w-0 truncate font-mono text-[12.5px] ${ready ? \"text-[var(--bd-fg)]\" : \"text-[var(--bd-muted)]\"}`}>{domainsOf(d)[0]}</span>\n          {ready ? (\n            <span className=\"ml-auto flex shrink-0 items-center\">\n              <CopyAddress url={domainsOf(d)[0]} />\n              <button type=\"button\" onClick={() => visit(domainsOf(d)[0])} aria-label={`Open ${domainsOf(d)[0]}`} className=\"grid size-8 place-items-center rounded-full text-[var(--bd-muted)] transition-colors hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\">\n                <ArrowUpRightIcon weight=\"regular\" className=\"size-3.5\" />\n              </button>\n            </span>\n          ) : (\n            <span className=\"ml-auto shrink-0 pr-2 text-[12px] text-[var(--bd-subtle)]\">Once it&apos;s ready</span>\n          )}\n        </div>\n      )}\n      {live ? (\n        <>\n          {/* The stages as a waterfall of time, and under the picked one, its last lines. */}\n          <Pipeline className=\"mt-7\" label={`Stages of ${d.sha.slice(0, 7)}`} stages={stages} selected={stage?.id ?? null} onSelect={setPicked}>\n            <div className=\"flex items-center justify-between gap-3 pb-1 pl-4 pr-2 pt-2\">\n              <span className=\"flex items-center gap-2 text-[12px] font-medium text-[var(--bd-muted)]\">\n                Output\n                {stage?.status === \"running\" && (\n                  <span className=\"inline-flex items-center gap-1.5 text-[var(--bd-fg)]\">\n                    <span className=\"size-1.5 rounded-full bg-[var(--bd-ui-wait)]\" aria-hidden />\n                    Live\n                  </span>\n                )}\n              </span>\n              <button type=\"button\" onClick={() => acts.inspect(d)} className=\"inline-flex h-7 items-center gap-1 rounded-full px-2.5 text-[12px] font-medium text-[var(--bd-muted)] transition-colors hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\">\n                Full log <ArrowUpRightIcon weight=\"regular\" className=\"size-3\" />\n              </button>\n            </div>\n            <div className=\"h-[80px] min-w-0 overflow-hidden px-4 pb-3 font-mono text-[11.5px] leading-[19px]\">\n              <AnimatePresence initial={false}>\n                {tail.map((l, i) => (\n                  <motion.p key={l.id} layout=\"position\" initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} className={`truncate ${i === tail.length - 1 && stage?.status === \"running\" ? \"text-[var(--bd-fg)]\" : l.level === \"error\" ? \"text-[var(--bd-ui-stop)]\" : \"text-[var(--bd-muted)]\"}`}>\n                    {l.message}\n                  </motion.p>\n                ))}\n              </AnimatePresence>\n              {!tail.length && <p className=\"text-[var(--bd-subtle)]\">Not started yet. It usually takes {formatDuration(stage?.estimate ?? 0)}.</p>}\n            </div>\n          </Pipeline>\n        </>\n      ) : (\n        // What's live, as a spec: how it was built, and where it's served.\n        <div className=\"mt-8 grid gap-x-12 gap-y-7 @3xl:grid-cols-[minmax(0,5fr)_minmax(0,7fr)]\">\n          <Facts d={d} />\n          <Domains d={d} />\n        </div>\n      )}\n    </section>\n  );\n}\n\ntype Roll = { id: string; key: number; head: number; plan: number[]; done: boolean };\n\nexport default function DeploymentsScreen() {\n  const [deploys, setDeploys] = useState(DEPLOYS);\n  const [current, setCurrent] = useState(\"dpl_a1f9\");\n  const [roll, setRoll] = useState<Roll | null>({ id: \"dpl_7c2e\", key: 1, head: LIVE_HEAD, plan: LIVE_PLAN, done: false });\n  const [since, setSince] = useState({ key: 0, ms: 0 });\n  const [open, setOpen] = useState<string | null>(null);\n  const [filters, setFilters] = useState<Filter[]>([]);\n  const made = useRef(100);\n\n  // The build in flight keeps its own time; when it's done it's ready, and production goes live on its own.\n  useEffect(() => {\n    if (!roll || roll.done) return;\n    const { id, key, head, plan } = roll;\n    const total = plan.reduce((a, b) => a + b, 0);\n    const start = Date.now();\n    const timer = window.setInterval(() => {\n      const ms = Date.now() - start;\n      if (head + ms < total) return setSince({ key, ms });\n      window.clearInterval(timer);\n      setSince({ key, ms: total - head });\n      setDeploys((all) => all.map((x) => (x.id === id ? { ...x, state: \"ready\", took: total, times: plan, when: \"just now\" } : x)));\n      setRoll((r) => (r && r.key === key ? { ...r, done: true } : r));\n    }, 250);\n    return () => window.clearInterval(timer);\n  }, [roll]);\n\n  const elapsed = roll ? Math.min(roll.plan.reduce((a, b) => a + b, 0), roll.head + (since.key === roll.key ? since.ms : 0)) : 0;\n  const rolling = roll ? deploys.find((x) => x.id === roll.id) : undefined;\n  // Production that finished building goes live by itself.\n  const production = rolling && roll?.done && rolling.env === \"production\" && rolling.state === \"ready\" ? rolling : null;\n  const live = current;\n  const stagesFor = (d: Deploy) => stagesOf(d, roll && roll.id === d.id && !roll.done ? { elapsed, plan: roll.plan } : null);\n\n  const say = (title: string, description: string, undo?: () => void) => toast(title, { tone: \"ok\", description, action: undo ? { label: \"Undo\", onClick: undo } : undefined });\n  const acts: Acts = {\n    promote: (d) => {\n      const was = current;\n      setDeploys((all) => all.map((x) => (x.id === d.id ? { ...x, env: \"production\" } : x)));\n      setCurrent(d.id);\n      if (roll?.id === d.id) setRoll(null);\n      say(\"Promoted to production\", `acme.com now serves ${d.sha.slice(0, 7)}.`, () => {\n        setDeploys((all) => all.map((x) => (x.id === d.id ? { ...x, env: \"preview\" } : x)));\n        setCurrent(was);\n      });\n    },\n    rollback: (d) => {\n      const was = current;\n      setCurrent(d.id);\n      say(\"Rolled back\", `acme.com serves ${d.sha.slice(0, 7)} again, from ${d.when}.`, () => setCurrent(was));\n    },\n    redeploy: (d, clean) => {\n      const id = `dpl_r${(made.current += 1)}`;\n      setDeploys((all) => [{ ...d, id, env: \"production\", branch: \"main\", author: \"Emily Carter\", state: \"building\", took: 0, when: \"just now\", day: \"Today\", stopped: undefined }, ...all]);\n      setRoll({ id, key: made.current, head: 0, plan: PRODUCTION_PLAN, done: false });\n      setOpen(null);\n      toast(clean ? \"Redeploying without the build cache\" : \"Redeploying\", { description: `${d.message}, to production.` });\n    },\n    cancel: () => {\n      if (!roll || roll.done) return;\n      const id = roll.id;\n      const at = STAGES[Math.max(0, stagesOf(rolling!, { elapsed, plan: roll.plan }).findIndex((s) => s.status === \"running\"))].id;\n      setDeploys((all) => all.map((x) => (x.id === id ? { ...x, state: \"canceled\", took: elapsed, stopped: { stage: at, note: \"Canceled by Emily Carter\" } } : x)));\n      setRoll(null);\n      toast(\"Build canceled\", { description: \"Production didn't change.\" });\n    },\n    inspect: (d) => setOpen(d.id),\n  };\n\n  // A production build that finished takes over from what was live.\n  useEffect(() => {\n    if (!production) return;\n    const t = window.setTimeout(() => {\n      setCurrent(production.id);\n      setRoll(null);\n      toast(\"Live in production\", { tone: \"ok\", description: `acme.com now serves ${production.sha.slice(0, 7)}.` });\n    }, 0);\n    return () => window.clearTimeout(t);\n  }, [production]);\n\n  const lead = rolling && roll && !production ? rolling : deploys.find((x) => x.id === live)!;\n  const leadLive = !!(rolling && roll && !production);\n  // The production that was live before the current one: what a roll back goes to.\n  const previous = deploys.find((x) => x.env === \"production\" && x.state === \"ready\" && x.id !== live && deploys.indexOf(x) > deploys.findIndex((y) => y.id === live));\n\n  const shown = deploys.filter((x) => filters.every((f) => f.values.includes(String(x[f.field as keyof Deploy])) !== !!f.not));\n  const days = [...new Set(shown.map((x) => x.day))];\n  const opened = deploys.find((x) => x.id === open);\n\n  return (\n    <AppFrame\n      page=\"deployments\"\n      crumbs={[\"Acme\", \"Storefront\", \"Deployments\"]}\n      actions={\n        <>\n          <Button variant=\"ghost\" size=\"sm\" className=\"@max-md:hidden\" onClick={() => visit(\"acme.com\")}>\n            Visit <ArrowUpRightIcon weight=\"regular\" />\n          </Button>\n          <SplitButton\n            size=\"sm\"\n            actions={[\n              { value: \"redeploy\", label: \"Redeploy\", description: \"Build production again, with the build cache.\", icon: <ArrowClockwiseIcon weight=\"regular\" /> },\n              { value: \"clean\", label: \"Redeploy clean\", description: \"From a fresh install, without the cache. Slower.\", icon: <StackIcon weight=\"duotone\" /> },\n            ]}\n            menuLabel=\"More ways to redeploy\"\n            disabled={!!(roll && !roll.done)}\n            onAction={(v) => acts.redeploy(deploys.find((x) => x.id === live)!, v === \"clean\")}\n          />\n        </>\n      }\n      panel={\n        <AnimatePresence>\n          {opened && (\n            <Side key=\"side\" label=\"Deployment\">\n              <Inspector key={opened.id} d={opened} stages={stagesFor(opened)} plan={roll && roll.id === opened.id ? roll.plan : undefined} current={opened.id === live} live={!!(roll && roll.id === opened.id && !roll.done)} acts={acts} onClose={() => setOpen(null)} />\n            </Side>\n          )}\n        </AnimatePresence>\n      }\n    >\n      {/* One column, never wider than the window: what's long inside truncates or wraps rather than pushing it out. */}\n      <div className=\"mx-auto grid w-full max-w-[1180px] grid-cols-[minmax(0,1fr)] gap-8 px-4 pb-16 pt-8 @2xl:px-8\">\n        <div>\n          <h1 className=\"text-[22px] font-semibold tracking-[-0.02em]\">Deployments</h1>\n          <p className=\"mt-1 text-[13.5px] text-[var(--bd-muted)]\">Pushes to main go to production. Every other branch gets a preview of its own.</p>\n        </div>\n\n        <Lead d={lead} stages={stagesFor(lead)} plan={leadLive ? roll!.plan : undefined} elapsed={elapsed} live={leadLive} current={lead.id === live} previous={previous} acts={acts} />\n\n        <div className=\"grid grid-cols-[minmax(0,1fr)] gap-4\">\n          <FilterBar noun=\"deployments\" fields={FIELDS} value={filters} onValueChange={setFilters}>\n            <span className=\"font-mono text-[12px] tabular-nums text-[var(--bd-muted)]\">\n              {shown.length} of {deploys.length}\n            </span>\n          </FilterBar>\n          {/* Every deployment, newest first, by day. */}\n          <div className=\"@container/list grid grid-cols-[minmax(0,1fr)] gap-5\">\n            {/* What each column is, once, over them all. */}\n            <div aria-hidden className=\"-mb-2 hidden grid-cols-[100px_150px_minmax(0,1fr)_64px_72px_32px] gap-4 px-3 text-[12px] text-[var(--bd-subtle)] @4xl/list:grid\">\n              <span>Status</span>\n              <span>Environment</span>\n              <span>Commit</span>\n              <span className=\"text-right\">Took</span>\n              <span className=\"text-right\">When</span>\n              <span />\n            </div>\n            {days.map((day) => (\n              <section key={day} aria-label={day}>\n                <h2 className=\"flex items-center gap-3 px-3 pb-2 text-[12px] font-medium text-[var(--bd-muted)]\">\n                  {day}\n                  <span className=\"h-px flex-1 bg-[var(--bd-line-subtle)]\" />\n                </h2>\n                <ul className=\"grid grid-cols-[minmax(0,1fr)]\">\n                  {shown\n                    .filter((x) => x.day === day)\n                    .map((x) => (\n                      <Row key={x.id} d={x} current={x.id === live} open={open === x.id} live={roll && roll.id === x.id && !roll.done ? elapsed : null} acts={acts} />\n                    ))}\n                </ul>\n              </section>\n            ))}\n            {!shown.length && <p className=\"px-3 py-10 text-center text-[13.5px] text-[var(--bd-muted)]\">No deployments match. Take a filter off to see more.</p>}\n          </div>\n        </div>\n      </div>\n    </AppFrame>\n  );\n}\n",
  "billing": "\"use client\";\n\nimport { ArrowUpRightIcon, CalendarDotsIcon, ChartLineIcon, ChatCircleIcon, CloudArrowUpIcon, CoinsIcon, CreditCardIcon, DownloadSimpleIcon, FolderIcon, FoldersIcon, FunctionIcon, GearSixIcon, HouseIcon, ImageSquareIcon, ListIcon, RocketLaunchIcon, TimerIcon, UserPlusIcon, UsersThreeIcon, WarningCircleIcon } from \"@phosphor-icons/react\";\nimport { useState, type ReactNode } from \"react\";\nimport {\n  AvatarGroup,\n  Breadcrumb,\n  Button,\n  Dialog,\n  DialogContent,\n  DialogTitle,\n  Switch,\n  toast,\n} from \"@basedraft/ui\";\nimport { AccountMenu } from \"@/components/basedraft/account-menu\";\nimport {\n  AppSidebar,\n  type SidebarSection,\n  type SidebarView,\n} from \"@/components/basedraft/app-sidebar\";\nimport { Pace } from \"@/components/basedraft/pace\";\nimport { Runway } from \"@/components/basedraft/runway\";\nimport { TopUp, type TopUpMethod } from \"@/components/basedraft/top-up\";\n\n/*\n * A workspace's usage and billing, in an app's frame. The balance leads, said as a sentence: what's\n * in credits and how long it lasts. Under it the runway: the balance day by day up to today, and\n * from there where it's heading at this pace, down to the day it runs out. Turn on the top-up that\n * runs by itself and the line ahead becomes a saw that never reaches zero; add credits and it jumps\n * today and reaches further. Under that, quieter, the period's usage paced against the plan, the\n * plan and what's on file as a ruled list, and the invoices, with a word only where one's out of\n * the ordinary. It fills the box it's in and scrolls inside, so give that box a height, like h-dvh.\n * The toasts need <Toaster /> once in your root layout.\n */\n\nconst SECTIONS: SidebarSection[] = [\n  {\n    items: [\n      { id: \"overview\", label: \"Overview\", icon: <HouseIcon weight=\"duotone\" />, href: \"/acme\" },\n      { id: \"projects\", label: \"Projects\", icon: <FoldersIcon weight=\"duotone\" />, count: 14, href: \"/acme/projects\" },\n      { id: \"deployments\", label: \"Deployments\", icon: <RocketLaunchIcon weight=\"duotone\" />, busy: true, href: \"/acme/storefront/deployments\" },\n      { id: \"analytics\", label: \"Analytics\", icon: <ChartLineIcon weight=\"duotone\" />, href: \"/acme/storefront/analytics\" },\n      { id: \"roadmap\", label: \"Roadmap\", icon: <CalendarDotsIcon weight=\"duotone\" />, tag: \"New\", href: \"/acme/roadmap\" },\n    ],\n  },\n  {\n    label: \"Pinned\",\n    action: { label: \"Pin a project\", onSelect: () => undefined },\n    items: [\n      { id: \"p-storefront\", label: \"storefront\", icon: <FolderIcon weight=\"duotone\" />, dot: true, href: \"/acme/storefront\" },\n      { id: \"p-docs\", label: \"docs\", icon: <FolderIcon weight=\"duotone\" />, href: \"/acme/docs\" },\n      { id: \"p-api\", label: \"api\", icon: <FolderIcon weight=\"duotone\" />, href: \"/acme/api\" },\n    ],\n  },\n  {\n    label: \"Workspace\",\n    items: [\n      { id: \"members\", label: \"Members\", icon: <UsersThreeIcon weight=\"duotone\" />, href: \"/acme/members\" },\n      { id: \"billing\", label: \"Usage and billing\", icon: <CreditCardIcon weight=\"duotone\" />, href: \"/acme/billing\" },\n      { id: \"settings\", label: \"Settings\", icon: <GearSixIcon weight=\"duotone\" />, href: \"/acme/settings\" },\n    ],\n  },\n];\n\n/* The sidebar's other view: what happened across the workspace, newest first. */\nconst VIEWS: SidebarView[] = [\n  { id: \"home\", label: \"Home\" },\n  {\n    id: \"activity\",\n    label: \"Activity\",\n    sections: [\n      {\n        label: \"Today\",\n        items: [\n          { id: \"a-promote\", label: \"7c2e9a1 is live\", icon: <RocketLaunchIcon weight=\"duotone\" />, count: \"2m\" },\n          { id: \"a-failed\", label: \"gift-cards failed\", icon: <WarningCircleIcon weight=\"duotone\" />, dot: true },\n          { id: \"a-comment\", label: \"Lauren on Checkout\", icon: <ChatCircleIcon weight=\"duotone\" />, count: \"1h\" },\n        ],\n      },\n      {\n        label: \"Yesterday\",\n        items: [\n          { id: \"a-credits\", label: \"$100 of credits\", icon: <CoinsIcon weight=\"duotone\" />, count: \"5pm\" },\n          { id: \"a-invite\", label: \"Tyler Hayes joined\", icon: <UserPlusIcon weight=\"duotone\" />, count: \"3pm\" },\n        ],\n      },\n    ],\n  },\n];\n\n/** The workspace's logo: basedraft's mark on an ink tile, standing in for yours. */\nfunction Mark() {\n  return (\n    <span className=\"grid size-6 shrink-0 place-items-center rounded-[7px] text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.14)]\">\n      <svg width={16} height={16} viewBox=\"0 0 40 40\" aria-hidden>\n        <path d=\"M6.85547 27.2182V12.6708C6.85547 11.2225 7.81635 9.95166 9.20555 9.56255L22.5167 5.83433C24.5479 5.26541 26.565 6.78215 26.5931 8.89956L26.7742 22.5376C26.7927 23.9328 25.9163 25.1818 24.6017 25.6336L11.1095 30.2712C9.02405 30.9879 6.85547 29.4317 6.85547 27.2182Z\" fill=\"currentColor\" />\n        <path d=\"M28.6015 10.8973L16.0958 17.0783L16.0698 17.0949C15.1656 17.6727 14.6078 18.6652 14.5825 19.7411L14.3291 30.5163C14.2766 32.7474 16.4414 34.3571 18.5513 33.6561L31.0303 29.5082C32.3457 29.0709 33.2339 27.8362 33.2339 26.4448V13.7925C33.2339 11.4025 30.7368 9.84189 28.6015 10.8973Z\" fill=\"currentColor\" fillOpacity={0.7} />\n      </svg>\n    </span>\n  );\n}\n\n/** The app around the page: the sidebar (a drawer where it doesn't fit), and the page on a panel under its header. */\nfunction AppFrame({ page, crumbs, actions, children }: { page: string; crumbs: string[]; actions?: ReactNode; children: ReactNode }) {\n  const [mode, setMode] = useState<\"side\" | \"drawer\">(\"side\");\n  const [open, setOpen] = useState(false);\n  return (\n    <div className=\"@container relative flex h-full min-h-0 bg-[var(--bd-well)] text-[var(--bd-fg)]\">\n      <AppSidebar\n        plain\n        contained\n        breakpoint={900}\n        sections={SECTIONS}\n        views={VIEWS}\n        active={page}\n        workspaces={[\n          { id: \"acme\", name: \"Acme\", plan: \"Team\", logo: <Mark /> },\n          { id: \"personal\", name: \"Personal\", plan: \"Hobby\" },\n        ]}\n        defaultWorkspace=\"acme\"\n        account={(rail) => (\n          <AccountMenu\n            user={{ name: \"Emily Carter\", email: \"emily@acme.com\" }}\n            trigger={rail ? \"face\" : \"row\"}\n            defaultNote=\"Closing the month\"\n            workspaces={[\n              { id: \"acme\", name: \"Acme\", role: \"Owner\", logo: <Mark /> },\n              { id: \"personal\", name: \"Personal\", role: \"Hobby\" },\n            ]}\n            workspace=\"acme\"\n            onPreferences={() => undefined}\n            onSignOut={() => undefined}\n          />\n        )}\n        onSearch={() => undefined}\n        open={open}\n        onOpenChange={setOpen}\n        onModeChange={setMode}\n      />\n      <div className=\"flex min-w-0 flex-1 flex-col @3xl:py-2 @3xl:pr-2\">\n        <main className=\"@container/main relative flex min-h-0 flex-1 flex-col overflow-hidden bg-[var(--bd-surface)] @3xl:rounded-[14px] @3xl:shadow-[0_0_0_1px_var(--bd-line-subtle),0_1px_3px_rgb(var(--bd-shade)/0.06)]\">\n          <header className=\"flex h-12 shrink-0 items-center gap-2 border-b border-[var(--bd-line-subtle)] px-3 @3xl:px-5\">\n            {mode === \"drawer\" && (\n              <button type=\"button\" onClick={() => setOpen(true)} aria-label=\"Open the menu\" className=\"grid size-8 place-items-center rounded-full text-[var(--bd-muted)] hover:bg-[rgb(var(--bd-ink)/0.06)]\">\n                <ListIcon weight=\"regular\" size={17} />\n              </button>\n            )}\n            <span className=\"min-w-0 @max-xl:hidden\">\n              <Breadcrumb items={crumbs.map((label, i) => (i < crumbs.length - 1 ? { label, href: `/${crumbs.slice(0, i + 1).join(\"/\").toLowerCase()}` } : { label }))} />\n            </span>\n            {/* Where there's no room for the trail, the page's name alone. */}\n            <span className=\"truncate text-[13.5px] font-medium @xl:hidden\">{crumbs.at(-1)}</span>\n            <div className=\"ml-auto flex items-center gap-2\">{actions}</div>\n          </header>\n          {/* It scrolls without a bar, the way an app's page does. */}\n          <div className=\"relative min-h-0 flex-1 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden\">{children}</div>\n        </main>\n      </div>\n    </div>\n  );\n}\n\nconst usd = (n: number) => new Intl.NumberFormat(\"en-US\", { style: \"currency\", currency: \"USD\", minimumFractionDigits: n % 1 ? 2 : 0, maximumFractionDigits: 2 }).format(n);\nconst round = (n: number) => Math.round(n * 100) / 100;\n\n/* What credits paid for each day, Oct 14 to today, Nov 12: quiet weekends, a launch on Oct 28. */\nconst SPEND = [7.2, 8.1, 9.4, 6.3, 4.1, 3.8, 8.8, 9.9, 10.6, 9.2, 7.7, 4.6, 4.2, 9.6, 15.8, 17.9, 13.1, 11.4, 6.2, 5.1, 10.2, 11.6, 12.4, 10.9, 9.8, 5.4, 4.9, 10.8, 12.1, 10.6];\nconst START = \"2026-10-14\";\n/* $100 was added on Oct 22, the ninth day. */\nconst TOPUPS: Record<number, number> = { 8: 100 };\n/** The balance at the end of each day, worked back from today's. */\nconst HISTORY = SPEND.reduceRight<number[]>((acc, _, i) => (i === SPEND.length - 1 ? [184.2] : [round(acc[0] + SPEND[i + 1] - (TOPUPS[i + 1] ?? 0)), ...acc]), []);\n/** The pace: what the last two weeks spent in a day. */\nconst BURN = round(SPEND.slice(-14).reduce((a, b) => a + b, 0) / 14);\nconst AUTO = { amount: 100, below: 20 };\n\nconst METHODS: TopUpMethod[] = [\n  { id: \"visa\", brand: \"Visa\", last4: \"4242\", expires: \"08/28\" },\n  { id: \"amex\", brand: \"Amex\", last4: \"1005\", expires: \"02/27\" },\n];\n\nconst DAY_OF_PERIOD = 12;\nconst PERIOD = 30;\n\n/* What the plan includes this period, used by day 12 of 30, and what each costs past it. */\nconst USAGE = [\n  { id: \"minutes\", label: \"Build minutes\", short: \"Minutes\", icon: <TimerIcon weight=\"duotone\" />, used: 2380, limit: 6000, unit: \"min\", rate: 0.008 },\n  { id: \"bandwidth\", label: \"Bandwidth\", short: \"Bandwidth\", icon: <CloudArrowUpIcon weight=\"duotone\" />, used: 312, limit: 1000, unit: \"GB\", rate: 0.15 },\n  { id: \"images\", label: \"Image optimizations\", short: \"Images\", icon: <ImageSquareIcon weight=\"duotone\" />, used: 3140, limit: 5000, unit: \"\", rate: 0.005 },\n  { id: \"functions\", label: \"Function invocations\", short: \"Functions\", icon: <FunctionIcon weight=\"duotone\" />, used: 1_420_000, limit: 5_000_000, unit: \"\", rate: 0.0000006 },\n].map((u) => ({ ...u, projected: Math.round((u.used / DAY_OF_PERIOD) * PERIOD) }));\n/* The first allowance that passes the plan at this pace: the day it does, and what the rest of the period costs. */\nconst PASSING = USAGE.filter((u) => u.projected > u.limit).map((u) => ({ ...u, on: Math.ceil(u.limit / (u.used / DAY_OF_PERIOD)), cost: Math.round((u.projected - u.limit) * u.rate) }));\n\n/* The invoices, a month at a time. */\ntype Line = { id: string; what: string; amount: number; refunded?: boolean };\nconst MONTHS: Array<{ month: string; paid: string; lines: Line[] }> = [\n  { month: \"November\", paid: \"Nov 1\", lines: [{ id: \"INV-2611\", what: \"Team plan, 8 seats\", amount: 160 }] },\n  {\n    month: \"October\",\n    paid: \"Oct 1 and 22\",\n    lines: [\n      { id: \"INV-2610\", what: \"Team plan, 8 seats\", amount: 160 },\n      { id: \"INV-2610-C\", what: \"Credits\", amount: 103.2 },\n    ],\n  },\n  { month: \"September\", paid: \"Sep 1\", lines: [{ id: \"INV-2609\", what: \"Team plan, 7 seats\", amount: 140 }] },\n  {\n    month: \"August\",\n    paid: \"Aug 1\",\n    lines: [\n      { id: \"INV-2608\", what: \"Team plan, 7 seats\", amount: 140 },\n      { id: \"INV-2608-C\", what: \"Credits\", amount: 51.75, refunded: true },\n    ],\n  },\n];\n\nconst SEATS = [\"Emily Carter\", \"Jake Morrison\", \"Sarah Mitchell\", \"Ryan Brooks\", \"Megan Turner\", \"Tyler Hayes\", \"Lauren Price\", \"Chris Bennett\"].map((name) => ({ name }));\n\n/** A part of the page under the lead: its title, with a note or an action at its end. */\nfunction Part({ title, end, children }: { title: string; end?: ReactNode; children: ReactNode }) {\n  return (\n    <section aria-label={title} className=\"grid min-w-0 content-start gap-5\">\n      <div className=\"flex h-8 items-center justify-between gap-3\">\n        <h2 className=\"text-[16px] font-semibold tracking-[-0.012em]\">{title}</h2>\n        {end}\n      </div>\n      {children}\n    </section>\n  );\n}\n\n/**\n * A bill, set the same way as every other so their parts line up across a row: what it is with an\n * action level with it, the amount, its lines, and a foot held to the bottom. The next one is raised.\n */\nfunction Bill({ next = false, label, action, amount, to, lines, foot }: { next?: boolean; label: string; action: ReactNode; amount: number; /** Where it's charged, beside the amount. */ to?: string; lines: Array<{ what: string; amount: string; quiet?: boolean }>; foot: ReactNode }) {\n  return (\n    <li className={`flex min-w-0 flex-col rounded-[18px] p-5 ${next ? \"@2xl/main:col-span-2 @5xl/main:col-span-1 bg-[var(--bd-raised)] shadow-[0_0_0_1px_rgb(var(--bd-ink)/0.08),0_1px_2px_rgb(var(--bd-shade)/0.05),0_12px_28px_-16px_rgb(var(--bd-shade)/0.25)]\" : \"shadow-[inset_0_0_0_1px_rgb(var(--bd-ink)/0.08)]\"}`}>\n      <div className=\"flex h-8 items-center justify-between gap-3\">\n        <p className={`truncate text-[14px] ${next ? \"font-medium text-[var(--bd-fg)]\" : \"text-[var(--bd-muted)]\"}`}>{label}</p>\n        {action}\n      </div>\n      <p className=\"mt-3 flex items-baseline justify-between gap-3\">\n        <span className=\"text-[28px] font-semibold leading-none tracking-[-0.028em] tabular-nums\">{usd(amount)}</span>\n        {to && <span className=\"truncate text-[13px] tabular-nums text-[var(--bd-muted)]\">{to}</span>}\n      </p>\n      <div className=\"mt-5 grid gap-1.5 border-t border-[var(--bd-line-subtle)] pt-3.5\">\n        {lines.map((l) => (\n          <p key={l.what} className=\"flex items-baseline justify-between gap-3 text-[13px]\">\n            <span className=\"min-w-0 truncate text-[var(--bd-muted)]\">{l.what}</span>\n            <span className={`shrink-0 tabular-nums ${l.quiet ? \"text-[var(--bd-muted)]\" : \"\"}`}>{l.amount}</span>\n          </p>\n        ))}\n      </div>\n      {/* At least a step of room, and all the rest, so every foot sits on the same line. */}\n      <div aria-hidden className=\"min-h-5 flex-1\" />\n      <div className=\"flex min-h-[46px] items-center justify-between gap-3 whitespace-nowrap border-t border-[var(--bd-line-subtle)] pt-3.5 text-[13px] text-[var(--bd-muted)]\">{foot}</div>\n    </li>\n  );\n}\n\nexport default function BillingScreen() {\n  const [added, setAdded] = useState(0);\n  const [adding, setAdding] = useState(false);\n  const [auto, setAuto] = useState(false);\n  const [topups, setTopups] = useState<Array<{ date: string; label: string }>>([{ date: \"2026-10-22\", label: \"+$100\" }]);\n  const history = [...HISTORY.slice(0, -1), round(HISTORY[HISTORY.length - 1] + added)];\n  const balance = history[history.length - 1];\n  const days = Math.floor(balance / BURN);\n  const runsOut = new Date(Date.UTC(2026, 10, 12 + days)).toLocaleDateString(\"en-US\", { month: \"short\", day: \"numeric\", timeZone: \"UTC\" });\n  const soon = (what: string) => toast(what, { description: \"In your app this opens its own page.\" });\n  const autoSwitch = (on: boolean) => {\n    setAuto(on);\n    toast(on ? \"Auto top-up on\" : \"Auto top-up off\", { description: on ? `Adds ${usd(AUTO.amount)} whenever credits fall under ${usd(AUTO.below)}.` : \"Credits only go up when you add them.\" });\n  };\n\n  return (\n    <AppFrame\n      page=\"billing\"\n      crumbs={[\"Acme\", \"Usage and billing\"]}\n      actions={\n        <Button variant=\"ghost\" size=\"sm\" onClick={() => soon(\"Pricing\")}>\n          Pricing <ArrowUpRightIcon weight=\"regular\" />\n        </Button>\n      }\n    >\n      <div className=\"mx-auto grid w-full max-w-[1040px] grid-cols-[minmax(0,1fr)] gap-14 px-4 pb-20 pt-9 @2xl:px-8 @2xl:pt-12\">\n        {/* The lead: the balance in a sentence, and its runway. */}\n        <section aria-label=\"Credits\" className=\"grid gap-9\">\n          <div className=\"flex flex-wrap items-start justify-between gap-x-10 gap-y-5\">\n            <div className=\"grid max-w-[620px] gap-3\">\n              <h1 className=\"text-balance text-[27px] font-semibold leading-[1.18] tracking-[-0.028em] @2xl/main:text-[34px]\">\n                <span className=\"tabular-nums\">{usd(balance)}</span> <span className=\"text-[var(--bd-subtle)]\">in credits, {auto ? \"topped up by itself before it runs low.\" : `enough until about ${runsOut}.`}</span>\n              </h1>\n              <p className=\"text-pretty text-[15px] leading-relaxed text-[var(--bd-muted)]\">\n                You spend about {usd(BURN)} a day, most of it on storefront. Whatever goes past the plan is paid from here, and credits never expire.\n              </p>\n            </div>\n            <div className=\"flex items-center gap-4\">\n              <label className=\"flex cursor-pointer items-center gap-2.5 text-[13.5px] text-[var(--bd-muted)]\">\n                Auto top-up\n                <Switch size=\"sm\" aria-label=\"Auto top-up\" checked={auto} onCheckedChange={autoSwitch} />\n              </label>\n              <Button size=\"sm\" onClick={() => setAdding(true)}>\n                Add credits\n              </Button>\n            </div>\n          </div>\n          <Runway history={history} start={START} burn={BURN} ahead={30} autoReload={auto ? AUTO : null} events={topups} marks={[{ date: \"2026-12-01\", label: \"Next bill\" }]} label=\"Credits\" height={220} />\n        </section>\n\n        <Part title=\"This period\" end={<span className=\"text-[13.5px] tabular-nums text-[var(--bd-muted)]\">Nov 1 to 30, day {DAY_OF_PERIOD}</span>}>\n          {/* The answer first: does this period cost more than the plan? */}\n          <p className=\"max-w-[720px] text-pretty text-[15px] leading-relaxed text-[var(--bd-muted)]\">\n            {PASSING.length ? (\n              <>\n                <span className=\"text-[var(--bd-fg)]\">{PASSING[0].label}</span> pass the plan around <span className=\"text-[var(--bd-fg)]\">Nov {PASSING[0].on}</span>, about {usd(PASSING[0].cost)} more from credits. Everything else fits.\n              </>\n            ) : (\n              \"Everything fits in the plan at this pace.\"\n            )}\n          </p>\n          <Pace items={USAGE} end=\"Nov 30\" label=\"This period's allowances\" />\n        </Part>\n\n        <Part\n          title=\"Bills\"\n          end={\n            <Button variant=\"ghost\" size=\"sm\" className=\"-mr-3.5\" onClick={() => soon(\"All invoices\")}>\n              All invoices\n            </Button>\n          }\n        >\n          {/* The next bill and the last two, each set the same way so their parts line up across. */}\n          <ul className=\"grid grid-cols-[minmax(0,1fr)] gap-3 @2xl/main:grid-cols-2 @5xl/main:grid-cols-3\">\n            <Bill\n              next\n              label=\"Next, Dec 1\"\n              action={\n                <Button variant=\"outline\" size=\"sm\" onClick={() => soon(\"Change plan\")}>\n                  Change plan\n                </Button>\n              }\n              amount={160}\n              to=\"Visa ···· 4242\"\n              lines={[\n                { what: \"Team plan, 8 seats\", amount: usd(160) },\n                ...PASSING.map((u) => ({ what: `${u.short} past the plan`, amount: `~${usd(u.cost)}`, quiet: true })),\n              ]}\n              foot={\n                <span className=\"flex items-center gap-2.5\">\n                  <AvatarGroup people={SEATS} max={3} size=\"sm\" />\n                  <span className=\"tabular-nums\">8 of 10 seats</span>\n                </span>\n              }\n            />\n            {MONTHS.slice(0, 2).map((m) => (\n              <Bill\n                key={m.month}\n                label={m.month}\n                action={\n                  <button type=\"button\" aria-label={`Download ${m.month}'s invoices`} onClick={() => toast(`${m.month} 2026.pdf`, { description: `${m.lines.length === 1 ? \"The invoice\" : `${m.lines.length} invoices`}, in one file.` })} className=\"-mr-1.5 grid size-8 place-items-center rounded-full text-[var(--bd-subtle)] transition-colors hover:bg-[rgb(var(--bd-ink)/0.06)] hover:text-[var(--bd-fg)]\">\n                    <DownloadSimpleIcon weight=\"regular\" className=\"size-4\" />\n                  </button>\n                }\n                amount={m.lines.reduce((a, l) => a + (l.refunded ? 0 : l.amount), 0)}\n                lines={m.lines.map((l) => ({ what: l.what, amount: usd(l.amount) }))}\n                foot={\n                  <>\n                    <span>Paid {m.paid}</span>\n                    <span className=\"tabular-nums\">{m.lines.length === 1 ? m.lines[0].id : `${m.lines.length} invoices`}</span>\n                  </>\n                }\n              />\n            ))}\n          </ul>\n          <p className=\"text-[13px] text-[var(--bd-subtle)]\">Receipts go to billing@acme.com. Usage past the plan comes out of credits, not the card.</p>\n        </Part>\n      </div>\n\n      <Dialog open={adding} onOpenChange={setAdding}>\n        <DialogContent size=\"md\" glow={false}>\n          <DialogTitle className=\"sr-only\">Add credits</DialogTitle>\n          <TopUp\n            plain\n            title=\"Add credits\"\n            balance={balance}\n            pace={{ perDay: BURN, from: \"2026-11-12\" }}\n            methods={METHODS}\n            autoReload={auto ? undefined : AUTO}\n            receipt=\"billing@acme.com\"\n            onConfirm={(r) =>\n              new Promise<void>((done) =>\n                setTimeout(() => {\n                  setAdded((a) => round(a + r.amount));\n                  setTopups((t) => [...t.filter((e) => e.date !== \"2026-11-12\"), { date: \"2026-11-12\", label: `+${usd(r.amount).replace(/\\.00$/, \"\")}` }]);\n                  if (r.autoReload) setAuto(true);\n                  done();\n                }, 1400),\n              )\n            }\n            onDone={() => setAdding(false)}\n            onAddMethod={() => soon(\"Add a card\")}\n          />\n        </DialogContent>\n      </Dialog>\n    </AppFrame>\n  );\n}\n",
  "roadmap": "\"use client\";\n\nimport { CalendarDotsIcon, ChartLineIcon, ChatCircleIcon, CircleHalfIcon, CoinsIcon, CreditCardIcon, CursorIcon, FolderIcon, FoldersIcon, GearSixIcon, HouseIcon, KanbanIcon, ListIcon, RocketLaunchIcon, UserIcon, UserPlusIcon, UsersThreeIcon, WarningCircleIcon } from \"@phosphor-icons/react\";\nimport { useReducedMotion } from \"motion/react\";\nimport { useEffect, useState, type ReactNode } from \"react\";\nimport { Badge, Breadcrumb, Segmented, Switch, toast } from \"@basedraft/ui\";\nimport { AccountMenu } from \"@/components/basedraft/account-menu\";\nimport {\n  AppSidebar,\n  type SidebarSection,\n  type SidebarView,\n} from \"@/components/basedraft/app-sidebar\";\nimport { FilterBar, type Filter, type FilterField } from \"@/components/basedraft/filter-bar\";\nimport { KanbanBoard, type KanbanColumn } from \"@/components/basedraft/kanban-board\";\nimport { LiveCursors, Viewers, type Presence } from \"@/components/basedraft/live-cursors\";\nimport { Roadmap, type RoadmapItem } from \"@/components/basedraft/roadmap\";\nimport { Share } from \"@/components/basedraft/share\";\nimport { Allowance } from \"@/components/basedraft/allowance\";\n\n/*\n * A quarter's plan with the team in it, in an app's frame. The work on a timeline you drag in\n * place, or the same work as a board where moving a card changes its status. Filter by team,\n * status or who has it. See who else is looking: their pointers move over the plan as they do,\n * and the Cursors switch hides them. Pick a piece of work to see it under the plan. It fills the\n * box it's in and scrolls inside, so give that box a height, like h-dvh. The toasts need\n * <Toaster /> once in your root layout.\n */\n\nconst SECTIONS: SidebarSection[] = [\n  {\n    items: [\n      { id: \"overview\", label: \"Overview\", icon: <HouseIcon weight=\"duotone\" />, href: \"/acme\" },\n      { id: \"projects\", label: \"Projects\", icon: <FoldersIcon weight=\"duotone\" />, count: 14, href: \"/acme/projects\" },\n      { id: \"deployments\", label: \"Deployments\", icon: <RocketLaunchIcon weight=\"duotone\" />, busy: true, href: \"/acme/storefront/deployments\" },\n      { id: \"analytics\", label: \"Analytics\", icon: <ChartLineIcon weight=\"duotone\" />, href: \"/acme/storefront/analytics\" },\n      { id: \"roadmap\", label: \"Roadmap\", icon: <CalendarDotsIcon weight=\"duotone\" />, tag: \"New\", href: \"/acme/roadmap\" },\n    ],\n  },\n  {\n    label: \"Pinned\",\n    action: { label: \"Pin a project\", onSelect: () => undefined },\n    items: [\n      { id: \"p-storefront\", label: \"storefront\", icon: <FolderIcon weight=\"duotone\" />, dot: true, href: \"/acme/storefront\" },\n      { id: \"p-docs\", label: \"docs\", icon: <FolderIcon weight=\"duotone\" />, href: \"/acme/docs\" },\n      { id: \"p-api\", label: \"api\", icon: <FolderIcon weight=\"duotone\" />, href: \"/acme/api\" },\n    ],\n  },\n  {\n    label: \"Workspace\",\n    items: [\n      { id: \"members\", label: \"Members\", icon: <UsersThreeIcon weight=\"duotone\" />, href: \"/acme/members\" },\n      { id: \"billing\", label: \"Usage and billing\", icon: <CreditCardIcon weight=\"duotone\" />, href: \"/acme/billing\" },\n      { id: \"settings\", label: \"Settings\", icon: <GearSixIcon weight=\"duotone\" />, href: \"/acme/settings\" },\n    ],\n  },\n];\n\n/* The sidebar's other view: what happened across the workspace, newest first. */\nconst VIEWS: SidebarView[] = [\n  { id: \"home\", label: \"Home\" },\n  {\n    id: \"activity\",\n    label: \"Activity\",\n    sections: [\n      {\n        label: \"Today\",\n        items: [\n          { id: \"a-promote\", label: \"7c2e9a1 is live\", icon: <RocketLaunchIcon weight=\"duotone\" />, count: \"2m\" },\n          { id: \"a-failed\", label: \"gift-cards failed\", icon: <WarningCircleIcon weight=\"duotone\" />, dot: true },\n          { id: \"a-comment\", label: \"Lauren on Checkout\", icon: <ChatCircleIcon weight=\"duotone\" />, count: \"1h\" },\n        ],\n      },\n      {\n        label: \"Yesterday\",\n        items: [\n          { id: \"a-credits\", label: \"$100 of credits\", icon: <CoinsIcon weight=\"duotone\" />, count: \"5pm\" },\n          { id: \"a-invite\", label: \"Tyler Hayes joined\", icon: <UserPlusIcon weight=\"duotone\" />, count: \"3pm\" },\n        ],\n      },\n    ],\n  },\n];\n\n/** The workspace's logo: basedraft's mark on an ink tile, standing in for yours. */\nfunction Mark() {\n  return (\n    <span className=\"grid size-6 shrink-0 place-items-center rounded-[7px] text-[var(--bd-ui-ink-text)] [background:var(--bd-ui-ink)] shadow-[inset_0_1px_0_rgb(255_255_255/0.14)]\">\n      <svg width={16} height={16} viewBox=\"0 0 40 40\" aria-hidden>\n        <path d=\"M6.85547 27.2182V12.6708C6.85547 11.2225 7.81635 9.95166 9.20555 9.56255L22.5167 5.83433C24.5479 5.26541 26.565 6.78215 26.5931 8.89956L26.7742 22.5376C26.7927 23.9328 25.9163 25.1818 24.6017 25.6336L11.1095 30.2712C9.02405 30.9879 6.85547 29.4317 6.85547 27.2182Z\" fill=\"currentColor\" />\n        <path d=\"M28.6015 10.8973L16.0958 17.0783L16.0698 17.0949C15.1656 17.6727 14.6078 18.6652 14.5825 19.7411L14.3291 30.5163C14.2766 32.7474 16.4414 34.3571 18.5513 33.6561L31.0303 29.5082C32.3457 29.0709 33.2339 27.8362 33.2339 26.4448V13.7925C33.2339 11.4025 30.7368 9.84189 28.6015 10.8973Z\" fill=\"currentColor\" fillOpacity={0.7} />\n      </svg>\n    </span>\n  );\n}\n\n/** The app around the page: the sidebar (a drawer where it doesn't fit), and the page on a panel under its header. */\nfunction AppFrame({ page, crumbs, actions, children }: { page: string; crumbs: string[]; actions?: ReactNode; children: ReactNode }) {\n  const [mode, setMode] = useState<\"side\" | \"drawer\">(\"side\");\n  const [open, setOpen] = useState(false);\n  return (\n    <div className=\"@container relative flex h-full min-h-0 bg-[var(--bd-well)] text-[var(--bd-fg)]\">\n      <AppSidebar\n        plain\n        contained\n        breakpoint={900}\n        sections={SECTIONS}\n        views={VIEWS}\n        active={page}\n        workspaces={[\n          { id: \"acme\", name: \"Acme\", plan: \"Team\", logo: <Mark /> },\n          { id: \"personal\", name: \"Personal\", plan: \"Hobby\" },\n        ]}\n        defaultWorkspace=\"acme\"\n        footer={(rail) => <Allowance label=\"Build minutes\" used={5046} limit={6000} projected={6210} note=\"Renews Nov 30\" compact={rail} className={rail ? \"mx-auto\" : undefined} />}\n        account={(rail) => (\n          <AccountMenu\n            user={{ name: \"Emily Carter\", email: \"emily@acme.com\" }}\n            trigger={rail ? \"face\" : \"row\"}\n            defaultNote=\"Planning the fourth quarter\"\n            workspaces={[\n              { id: \"acme\", name: \"Acme\", role: \"Owner\", logo: <Mark /> },\n              { id: \"personal\", name: \"Personal\", role: \"Hobby\" },\n            ]}\n            workspace=\"acme\"\n            onPreferences={() => undefined}\n            onSignOut={() => undefined}\n          />\n        )}\n        onSearch={() => undefined}\n        open={open}\n        onOpenChange={setOpen}\n        onModeChange={setMode}\n      />\n      <div className=\"flex min-w-0 flex-1 flex-col @3xl:py-2 @3xl:pr-2\">\n        <main className=\"flex min-h-0 flex-1 flex-col overflow-hidden bg-[var(--bd-surface)] @3xl:rounded-[14px] @3xl:shadow-[0_0_0_1px_var(--bd-line-subtle),0_1px_3px_rgb(var(--bd-shade)/0.06)]\">\n          <header className=\"flex h-12 shrink-0 items-center gap-2 border-b border-[var(--bd-line-subtle)] px-3 @3xl:px-5\">\n            {mode === \"drawer\" && (\n              <button type=\"button\" onClick={() => setOpen(true)} aria-label=\"Open the menu\" className=\"grid size-8 place-items-center rounded-full text-[var(--bd-muted)] hover:bg-[rgb(var(--bd-ink)/0.06)]\">\n                <ListIcon weight=\"regular\" size={17} />\n              </button>\n            )}\n            <span className=\"min-w-0 @max-xl:hidden\">\n              <Breadcrumb items={crumbs.map((label, i) => (i < crumbs.length - 1 ? { label, href: `/${crumbs.slice(0, i + 1).join(\"/\").toLowerCase()}` } : { label }))} />\n            </span>\n            {/* Where there's no room for the trail, the page's name alone. */}\n            <span className=\"truncate text-[13.5px] font-medium @xl:hidden\">{crumbs.at(-1)}</span>\n            <div className=\"ml-auto flex items-center gap-2\">{actions}</div>\n          </header>\n          <div className=\"relative min-h-0 flex-1 overflow-y-auto\">{children}</div>\n        </main>\n      </div>\n    </div>\n  );\n}\n\ntype Status = NonNullable<RoadmapItem[\"status\"]>;\n\nconst WORK: RoadmapItem[] = [\n  { id: \"checkout\", group: \"Storefront\", title: \"Checkout redesign\", start: \"2026-10-12\", end: \"2026-11-06\", status: \"active\", progress: 0.62, owner: \"Jake Morrison\" },\n  { id: \"gift\", group: \"Storefront\", title: \"Gift cards\", start: \"2026-11-02\", end: \"2026-11-27\", status: \"planned\", owner: \"Sarah Mitchell\" },\n  { id: \"search\", group: \"Storefront\", title: \"Search that forgives typos\", start: \"2026-11-16\", end: \"2026-12-18\", status: \"planned\", owner: \"Megan Turner\" },\n  { id: \"fra1\", group: \"Platform\", title: \"Move to fra1\", start: \"2026-10-05\", end: \"2026-10-23\", status: \"done\", owner: \"Ryan Brooks\" },\n  { id: \"edge\", group: \"Platform\", title: \"Edge caching\", start: \"2026-10-26\", end: \"2026-11-20\", status: \"risk\", progress: 0.3, owner: \"Ryan Brooks\" },\n  { id: \"logs\", group: \"Platform\", title: \"Logs to S3\", start: \"2026-11-23\", end: \"2026-12-11\", status: \"planned\", owner: \"Tyler Hayes\" },\n  { id: \"launch\", group: \"Growth\", title: \"Autumn launch\", start: \"2026-10-05\", end: \"2026-10-16\", status: \"done\", owner: \"Emily Carter\" },\n  { id: \"referrals\", group: \"Growth\", title: \"Referral credits\", start: \"2026-10-19\", end: \"2026-11-13\", status: \"active\", progress: 0.45, owner: \"Lauren Price\" },\n  { id: \"holiday\", group: \"Growth\", title: \"Holiday campaign\", start: \"2026-11-09\", end: \"2026-12-24\", status: \"planned\", owner: \"Emily Carter\" },\n];\nconst NAMES = [\"Jake Morrison\", \"Sarah Mitchell\", \"Megan Turner\", \"Ryan Brooks\", \"Tyler Hayes\", \"Emily Carter\", \"Lauren Price\"];\nconst STATUSES: Array<{ id: Status; title: string }> = [\n  { id: \"planned\", title: \"Planned\" },\n  { id: \"active\", title: \"Under way\" },\n  { id: \"risk\", title: \"At risk\" },\n  { id: \"done\", title: \"Done\" },\n];\nconst FIELDS: FilterField[] = [\n  { id: \"group\", label: \"Team\", icon: <UsersThreeIcon weight=\"duotone\" />, plural: \"teams\", options: [\"Storefront\", \"Platform\", \"Growth\"].map((t) => ({ value: t, label: t })) },\n  { id: \"status\", label: \"Status\", icon: <CircleHalfIcon weight=\"duotone\" />, plural: \"statuses\", options: STATUSES.map((s) => ({ value: s.id, label: s.title })) },\n  { id: \"owner\", label: \"Owner\", icon: <UserIcon weight=\"duotone\" />, plural: \"people\", options: NAMES.map((n) => ({ value: n, label: n })) },\n];\n\n/** The others here, by the colors their pointers and faces wear. */\nconst OTHERS = [\n  { id: \"jake\", name: \"Jake\", color: \"oklch(0.62 0.12 250)\" },\n  { id: \"ryan\", name: \"Ryan\", color: \"oklch(0.64 0.11 160)\" },\n  { id: \"lauren\", name: \"Lauren\", color: \"oklch(0.66 0.12 60)\" },\n];\n/** Where each of them reads: a center on the plan, how far they wander from it, and how fast. */\nconst DRIFT: Record<string, { x: number; y: number; rx: number; ry: number; speed: number; phase: number }> = {\n  jake: { x: 0.5, y: 0.31, rx: 0.09, ry: 0.04, speed: 0.00095, phase: 0 },\n  ryan: { x: 0.66, y: 0.57, rx: 0.08, ry: 0.045, speed: 0.0008, phase: 2.1 },\n  lauren: { x: 0.37, y: 0.8, rx: 0.09, ry: 0.03, speed: 0.00088, phase: 4.2 },\n};\n\n/**\n * The others' pointers over the plan, drifting the way people's do as they read: slow loops of\n * two speeds mixed, each their own, worked out fifteen times a second with the cursors' glide\n * filling in between. Its own little component, so only the pointers draw again, not the plan.\n */\nfunction Crowd({ on, children }: { on: boolean; children: ReactNode }) {\n  const [t, setT] = useState(0);\n  const still = useReducedMotion();\n  useEffect(() => {\n    if (!on || still) return;\n    let raf = 0;\n    let last = 0;\n    const start = performance.now();\n    const loop = (now: number) => {\n      raf = requestAnimationFrame(loop);\n      if (now - last < 66) return;\n      last = now;\n      setT(now - start);\n    };\n    raf = requestAnimationFrame(loop);\n    return () => cancelAnimationFrame(raf);\n  }, [on, still]);\n  const at = (id: string) => {\n    const d = DRIFT[id];\n    const a = t * d.speed + d.phase;\n    return { x: d.x + d.rx * (Math.sin(a) * 0.75 + Math.sin(a * 2.3 + 1) * 0.25), y: d.y + d.ry * (Math.sin(a * 1.6 + 2) * 0.8 + Math.cos(a * 3.1) * 0.2) };\n  };\n  const second = Math.floor(t / 1000);\n  const people: Presence[] = OTHERS.map((o) => ({\n    ...o,\n    ...at(o.id),\n    message: o.id === \"jake\" && second % 12 < 6 ? \"Checkout slips a week?\" : undefined,\n    typing: o.id === \"lauren\" && second % 10 >= 7,\n  }));\n  return (\n    <LiveCursors people={on ? people : []} you={{ id: \"emily\", name: \"Emily\", color: \"oklch(0.3 0 0)\" }} className=\"min-w-0 rounded-[16px]\">\n      {children}\n    </LiveCursors>\n  );\n}\n\nconst short = (iso: string) => new Date(`${iso}T00:00:00Z`).toLocaleDateString(\"en-US\", { month: \"short\", day: \"numeric\", timeZone: \"UTC\" });\n\nexport default function RoadmapScreen() {\n  const [items, setItems] = useState(WORK);\n  const [view, setView] = useState(\"timeline\");\n  const [scale, setScale] = useState<\"week\" | \"month\">(\"week\");\n  const [filters, setFilters] = useState<Filter[]>([]);\n  const [picked, setPicked] = useState<string | null>(\"edge\");\n  // Everyone else's pointers and what they say, over the plan; off, only their faces show who's here.\n  const [cursors, setCursors] = useState(true);\n\n  const shown = items.filter((i) => filters.every((f) => f.values.includes(String(i[f.field as keyof RoadmapItem])) !== !!f.not));\n  const item = items.find((i) => i.id === picked);\n  const columns: KanbanColumn[] = STATUSES.map((s) => ({\n    id: s.id,\n    title: s.title,\n    cards: shown.filter((i) => i.status === s.id).map((i) => ({ id: i.id, title: i.title, tags: [i.group ?? \"\"], people: i.owner ? [i.owner] : [], meta: `${short(i.start)} to ${short(i.end)}` })),\n  }));\n  const moveCards = (next: KanbanColumn[]) => {\n    const status = new Map(next.flatMap((c) => c.cards.map((card) => [card.id, c.id as Status] as const)));\n    setItems((all) => all.map((i) => (status.has(i.id) && status.get(i.id) !== i.status ? { ...i, status: status.get(i.id), progress: status.get(i.id) === \"done\" ? 1 : i.progress } : i)));\n  };\n\n  return (\n    <AppFrame\n      page=\"roadmap\"\n      crumbs={[\"Acme\", \"Roadmap\"]}\n      actions={\n        <>\n          <label className=\"flex cursor-pointer items-center gap-2 rounded-full py-1 pl-2.5 pr-1 text-[12.5px] text-[var(--bd-muted)] transition-colors hover:text-[var(--bd-fg)]\">\n            <CursorIcon size={15} weight=\"duotone\" className=\"shrink-0\" />\n            <span className=\"@max-md:hidden\">Cursors</span>\n            <Switch size=\"sm\" aria-label=\"Show everyone's cursors\" checked={cursors} onCheckedChange={setCursors} />\n          </label>\n          <Viewers people={OTHERS} max={3} className=\"@max-md:hidden\" />\n          <Share\n            title=\"Fourth quarter\"\n            url=\"https://relay.app/acme/roadmap\"\n            workspace=\"Acme\"\n            defaultPeople={[\n              { id: \"emily\", name: \"Emily Carter\", email: \"emily@acme.com\", role: \"owner\", you: true },\n              { id: \"jake\", name: \"Jake Morrison\", email: \"jake@acme.com\", role: \"edit\" },\n              { id: \"ryan\", name: \"Ryan Brooks\", email: \"ryan@acme.com\", role: \"edit\" },\n              { id: \"lauren\", name: \"Lauren Price\", email: \"lauren@acme.com\", role: \"view\" },\n            ]}\n            onInvite={(emails, role) => toast(emails.length === 1 ? `Invited ${emails[0]}` : `${emails.length} people invited`, { tone: \"ok\", description: role === \"edit\" ? \"They can edit the plan.\" : \"They can view the plan.\" })}\n            onCopy={() => toast(\"Link copied\", { description: \"Anyone in Acme can open it.\" })}\n          />\n        </>\n      }\n    >\n      <div className=\"mx-auto grid w-full max-w-[1280px] gap-5 px-4 pb-12 pt-7 @2xl:px-8\">\n        <div className=\"flex flex-wrap items-end justify-between gap-4\">\n          <div>\n            <h1 className=\"text-[22px] font-semibold tracking-[-0.02em]\">Fourth quarter</h1>\n            <p className=\"mt-1 text-[13.5px] text-[var(--bd-muted)]\">\n              {items.length} pieces of work across 3 teams. {items.filter((i) => i.status === \"risk\").length} at risk, {items.filter((i) => i.status === \"done\").length} done.\n            </p>\n          </div>\n          <div className=\"flex flex-wrap items-center gap-2\">\n            {view === \"timeline\" && (\n              <Segmented\n                size=\"sm\"\n                label=\"Scale\"\n                value={scale}\n                onValueChange={(v) => setScale(v as \"week\" | \"month\")}\n                options={[\n                  { value: \"week\", label: \"Weeks\" },\n                  { value: \"month\", label: \"Quarter\" },\n                ]}\n              />\n            )}\n            <Segmented\n              size=\"sm\"\n              label=\"View\"\n              value={view}\n              onValueChange={setView}\n              options={[\n                { value: \"timeline\", label: \"Timeline\", icon: <CalendarDotsIcon weight=\"duotone\" /> },\n                { value: \"board\", label: \"Board\", icon: <KanbanIcon weight=\"duotone\" /> },\n              ]}\n            />\n          </div>\n        </div>\n\n        <FilterBar noun=\"work\" fields={FIELDS} value={filters} onValueChange={setFilters}>\n          <span className=\"font-mono text-[12px] tabular-nums text-[var(--bd-muted)]\">\n            {shown.length} of {items.length}\n          </span>\n        </FilterBar>\n\n        <div className=\"grid gap-5\">\n          <Crowd on={cursors}>\n            {view === \"timeline\" ? (\n              <Roadmap\n                items={shown}\n                onItemsChange={(_, moved) => setItems((all) => all.map((i) => (i.id === moved.id ? moved : i)))}\n                from=\"2026-10-05\"\n                days={scale === \"week\" ? 56 : 91}\n                today=\"2026-10-30\"\n                scale={scale}\n                selected={picked}\n                onSelect={(i) => setPicked(i.id)}\n              />\n            ) : (\n              <KanbanBoard label=\"Roadmap board\" columns={columns} onColumnsChange={moveCards} size=\"sm\" />\n            )}\n          </Crowd>\n\n          {/* The piece of work that's picked. */}\n          {item && (\n            <aside className=\"grid gap-x-8 gap-y-4 rounded-[20px] bg-[var(--bd-surface)] p-5 shadow-[0_0_0_1px_rgb(var(--bd-ink)/0.08),0_1px_2px_rgb(var(--bd-shade)/0.05)] @4xl:grid-cols-[minmax(0,1.2fr)_repeat(3,minmax(0,1fr))] @4xl:items-center\">\n              <div className=\"min-w-0\">\n                <p className=\"text-[12px] text-[var(--bd-muted)]\">{item.group}</p>\n                <p className=\"mt-0.5 flex flex-wrap items-center gap-2 text-[16px] font-semibold tracking-[-0.01em]\">\n                  {item.title}\n                  <Badge variant=\"outline\" dot={item.status === \"done\" ? \"ok\" : item.status === \"risk\" ? \"wait\" : item.status === \"active\" ? \"ok\" : \"idle\"}>\n                    {STATUSES.find((s) => s.id === item.status)?.title}\n                  </Badge>\n                </p>\n              </div>\n              <div>\n                <p className=\"text-[12px] text-[var(--bd-muted)]\">Dates</p>\n                <p className=\"mt-0.5 font-mono text-[12.5px] tabular-nums\">\n                  {short(item.start)} to {short(item.end)}\n                </p>\n              </div>\n              <div>\n                <p className=\"text-[12px] text-[var(--bd-muted)]\">Owner</p>\n                <p className=\"mt-0.5 text-[13px]\">{item.owner}</p>\n              </div>\n              <div>\n                <p className=\"flex justify-between text-[12px] text-[var(--bd-muted)]\">\n                  Progress <span className=\"font-mono tabular-nums text-[var(--bd-fg)]\">{Math.round((item.progress ?? (item.status === \"done\" ? 1 : 0)) * 100)}%</span>\n                </p>\n                <div className=\"mt-2 h-1.5 overflow-hidden rounded-full bg-[var(--bd-ui-track)]\">\n                  <div className={`h-full rounded-full transition-[width] duration-500 ${item.status === \"risk\" ? \"bg-[var(--bd-ui-wait)]\" : \"bg-[var(--bd-fg)]\"}`} style={{ width: `${(item.progress ?? (item.status === \"done\" ? 1 : 0)) * 100}%` }} />\n                </div>\n              </div>\n            </aside>\n          )}\n        </div>\n      </div>\n    </AppFrame>\n  );\n}\n"
};
